@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#EDIFACT_INVOIC_Story>
    a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC Ontology" ;
    rdfs:comment "Ontology for modeling UN/EDIFACT D96A INVOIC messages, segments, and business document semantics for industrial procurement." .

#################################################################
# CLASSES
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "Top-level envelope containing one or more EDIFACT messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A message within an interchange, such as INVOIC." .

:InvoiceMessage a owl:Class ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "A message representing an invoice (INVOIC)." ;
    rdfs:subClassOf :Message .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment is a logical grouping of data elements in EDIFACT." .

:BGM_Segment a owl:Class ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." ;
    rdfs:subClassOf :Segment .

:NADSegment a owl:Class ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment for participant details." ;
    rdfs:subClassOf :Segment .

:DTMSegment a owl:Class ;
    rdfs:label "DTM Segment" ;
    rdfs:comment "Date/Time/Period segment, with subclasses for qualifiers (e.g., 137: Document Date)." ;
    rdfs:subClassOf :Segment .

:MOASegment a owl:Class ;
    rdfs:label "MOA Segment" ;
    rdfs:comment "Monetary Amount segment, for invoice totals, taxes, etc." ;
    rdfs:subClassOf :Segment .

:QTYSegment a owl:Class ;
    rdfs:label "QTY Segment" ;
    rdfs:comment "Quantity segment, with qualifiers (e.g., invoiced quantity)." ;
    rdfs:subClassOf :Segment .

:MEASegment a owl:Class ;
    rdfs:label "MEA Segment" ;
    rdfs:comment "Measurements segment, for reporting measurements relevant to line items." ;
    rdfs:subClassOf :Segment .

:ALCSegment a owl:Class ;
    rdfs:label "ALC Segment" ;
    rdfs:comment "Allowances/Charges segment." ;
    rdfs:subClassOf :Segment .

:TAXSegment a owl:Class ;
    rdfs:label "TAX Segment" ;
    rdfs:comment "Tax details segment, for specifying tax categories, rates, and amounts." ;
    rdfs:subClassOf :Segment .

:RFFSegment a owl:Class ;
    rdfs:label "RFF Segment" ;
    rdfs:comment "Reference segment, used for document and line-level referencing." ;
    rdfs:subClassOf :Segment .

:CompositeElement a owl:Class ;
    rdfs:label "Composite Element" ;
    rdfs:comment "A composite data element in a segment." .

:SimpleElement a owl:Class ;
    rdfs:label "Simple Element" ;
    rdfs:comment "A simple (atomic) data element in a segment or composite." ;
    rdfs:subClassOf :CompositeElement .

:HeaderSection a owl:Class ;
    rdfs:label "Header Section" ;
    rdfs:comment "Section containing document-level data (dates, references, etc.)." ;
    rdfs:subClassOf :CompositeElement .

:DetailSection a owl:Class ;
    rdfs:label "Detail Section" ;
    rdfs:comment "Section containing invoice line items." ;
    rdfs:subClassOf :CompositeElement .

:SummarySection a owl:Class ;
    rdfs:label "Summary Section" ;
    rdfs:comment "Section summarizing totals, taxes, etc." ;
    rdfs:subClassOf :CompositeElement .

:InvoiceLine a owl:Class ;
    rdfs:label "Invoice Line" ;
    rdfs:comment "A single line item in the invoice." ;
    rdfs:subClassOf :DetailSection .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in the invoice, such as buyer or supplier." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the invoice (e.g., Buyer, Delivery Party)." .

:BuyerRole a owl:Class ;
    rdfs:label "Buyer Role" ;
    rdfs:comment "Role of buyer in the invoice." ;
    rdfs:subClassOf :AgentRole .

:DeliveryPartyRole a owl:Class ;
    rdfs:label "Delivery Party Role" ;
    rdfs:comment "Role of delivery party in the invoice." ;
    rdfs:subClassOf :AgentRole .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "Physical or logical address associated with an organization." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "GLN identifier for organization locations." ;
    rdfs:subClassOf :SimpleElement .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "An item being sold in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "Price information for an item." ;
    rdfs:subClassOf :SimpleElement .

:Quantity a owl:Class ;
    rdfs:label "Quantity" ;
    rdfs:comment "Quantity information for an item or line." ;
    rdfs:subClassOf :SimpleElement .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "Tax information related to items or invoice." ;
    rdfs:subClassOf :SimpleElement .

:ReferenceNumber a owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "A reference number (e.g., invoice number, order number)." ;
    rdfs:subClassOf :SimpleElement .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice is assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint used for automated validation of invoice data." .

:P2P_O_Alignment a owl:Class ;
    rdfs:label "P2P-O Alignment" ;
    rdfs:comment "Alignment node for Purchase-to-Pay Ontology." .

:EN16931_Alignment a owl:Class ;
    rdfs:label "EN 16931 Alignment" ;
    rdfs:comment "Alignment node for EN 16931 European Standard." .

:InvoiceAmount a owl:Class ;
    rdfs:label "Invoice Amount" ;
    rdfs:comment "Class for invoice total amount, used for reification if needed." ;
    rdfs:subClassOf :SimpleElement .

:InvoiceNumber a owl:Class ;
    rdfs:label "Invoice Number" ;
    rdfs:comment "Class for invoice number, used for reification if needed." ;
    rdfs:subClassOf :SimpleElement .

# Pivot Classes
:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "Reifies the assignment of a role to an organization within an invoice context." .

:InvoiceLineItemDetail a owl:Class ;
    rdfs:label "Invoice Line Item Detail" ;
    rdfs:comment "Reifies the details of an invoice line item, such as price, quantity, and tax." ;
    rdfs:subClassOf :InvoiceLine .

#################################################################
# OBJECT PROPERTIES
#################################################################

:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Relates an InterchangeEnvelope to its contained Message(s)." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope a owl:ObjectProperty ;
    rdfs:label "is contained in envelope" ;
    rdfs:comment "A Message is contained in an InterchangeEnvelope. Inverse of containsMessage." ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    owl:inverseOf :containsMessage .

:hasSegment a owl:ObjectProperty ;
    rdfs:label "has segment" ;
    rdfs:comment "Relates a Message to its constituent Segments." ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:label "is segment of" ;
    rdfs:comment "A Segment is part of a Message. Inverse of hasSegment." ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    owl:inverseOf :hasSegment .

:hasSection a owl:ObjectProperty ;
    rdfs:label "has section" ;
    rdfs:comment "Relates an InvoiceMessage to its major logical sections (header, detail, summary)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :CompositeElement ;
    owl:inverseOf :isSectionOf .

:isSectionOf a owl:ObjectProperty ;
    rdfs:label "is section of" ;
    rdfs:comment "A CompositeElement is a section of an InvoiceMessage. Inverse of hasSection." ;
    rdfs:domain :CompositeElement ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasSection .

:hasInvoiceLine a owl:ObjectProperty ;
    rdfs:label "has invoice line" ;
    rdfs:comment "Relates a DetailSection to its InvoiceLine(s)." ;
    rdfs:domain :DetailSection ;
    rdfs:range :InvoiceLine ;
    owl:inverseOf :isInvoiceLineOf .

:isInvoiceLineOf a owl:ObjectProperty ;
    rdfs:label "is invoice line of" ;
    rdfs:comment "An InvoiceLine is part of a DetailSection. Inverse of hasInvoiceLine." ;
    rdfs:domain :InvoiceLine ;
    rdfs:range :DetailSection ;
    owl:inverseOf :hasInvoiceLine .

:hasItem a owl:ObjectProperty ;
    rdfs:label "has item" ;
    rdfs:comment "Relates an InvoiceLine to the Item being sold." ;
    rdfs:domain :InvoiceLine ;
    rdfs:range :Item ;
    owl:inverseOf :isItemOfInvoiceLine .

:isItemOfInvoiceLine a owl:ObjectProperty ;
    rdfs:label "is item of invoice line" ;
    rdfs:comment "An Item is part of an InvoiceLine. Inverse of hasItem." ;
    rdfs:domain :Item ;
    rdfs:range :InvoiceLine ;
    owl:inverseOf :hasItem .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Relates an Organization to its OrganizationRoleAssignment(s)." ;
    rdfs:domain :Organization ;
    rdfs:range :OrganizationRoleAssignment ;
    owl:inverseOf :isRoleAssignmentOf .

:isRoleAssignmentOf a owl:ObjectProperty ;
    rdfs:label "is role assignment of" ;
    rdfs:comment "An OrganizationRoleAssignment is for an Organization. Inverse of hasRoleAssignment." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Organization ;
    owl:inverseOf :hasRoleAssignment .

:assignedRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "assigned role" ;
    rdfs:comment "Relates an OrganizationRoleAssignment to the AgentRole." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :AgentRole ;
    owl:inverseOf :isRoleAssignedTo .

:isRoleAssignedTo a owl:ObjectProperty ;
    rdfs:label "is role assigned to" ;
    rdfs:comment "An AgentRole is assigned to an OrganizationRoleAssignment. Inverse of assignedRole." ;
    rdfs:domain :AgentRole ;
    rdfs:range :OrganizationRoleAssignment ;
    owl:inverseOf :assignedRole .

:assignedToInvoice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "assigned to invoice" ;
    rdfs:comment "Relates an OrganizationRoleAssignment to the InvoiceMessage context." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasRoleAssignmentInInvoice .

:hasRoleAssignmentInInvoice a owl:ObjectProperty ;
    rdfs:label "has role assignment in invoice" ;
    rdfs:comment "An InvoiceMessage has a role assignment. Inverse of assignedToInvoice." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :OrganizationRoleAssignment ;
    owl:inverseOf :assignedToInvoice .

:hasAddress a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has address" ;
    rdfs:comment "Relates an Organization to its Address." ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    owl:inverseOf :isAddressOf .

:isAddressOf a owl:ObjectProperty ;
    rdfs:label "is address of" ;
    rdfs:comment "An Address belongs to an Organization. Inverse of hasAddress." ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    owl:inverseOf :hasAddress .

:hasBusinessProcess a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has business process" ;
    rdfs:comment "Relates an InvoiceMessage to a BusinessProcess." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    owl:inverseOf :isBusinessProcessOf .

:isBusinessProcessOf a owl:ObjectProperty ;
    rdfs:label "is business process of" ;
    rdfs:comment "A BusinessProcess relates to an InvoiceMessage. Inverse of hasBusinessProcess." ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasBusinessProcess .

:isAlignedWithP2P_O a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "is aligned with P2P-O" ;
    rdfs:comment "Relates an InvoiceMessage to a P2P_O_Alignment node." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :P2P_O_Alignment ;
    owl:inverseOf :alignsP2POToInvoice .

:alignsP2POToInvoice a owl:ObjectProperty ;
    rdfs:label "aligns P2P-O to invoice" ;
    rdfs:comment "A P2P_O_Alignment aligns to an InvoiceMessage. Inverse of isAlignedWithP2P_O." ;
    rdfs:domain :P2P_O_Alignment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :isAlignedWithP2P_O .

:isAlignedWithEN16931 a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "is aligned with EN16931" ;
    rdfs:comment "Relates an InvoiceMessage to an EN16931_Alignment node." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :EN16931_Alignment ;
    owl:inverseOf :alignsEN16931ToInvoice .

:alignsEN16931ToInvoice a owl:ObjectProperty ;
    rdfs:label "aligns EN16931 to invoice" ;
    rdfs:comment "An EN16931_Alignment aligns to an InvoiceMessage. Inverse of isAlignedWithEN16931." ;
    rdfs:domain :EN16931_Alignment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :isAlignedWithEN16931 .

:hasValidationConstraint a owl:ObjectProperty ;
    rdfs:label "has validation constraint" ;
    rdfs:comment "Relates an InvoiceMessage to a ValidationConstraint." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ValidationConstraint ;
    owl:inverseOf :isValidationConstraintOf .

:isValidationConstraintOf a owl:ObjectProperty ;
    rdfs:label "is validation constraint of" ;
    rdfs:comment "A ValidationConstraint is for an InvoiceMessage. Inverse of hasValidationConstraint." ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasValidationConstraint .

:hasDTMSegment a owl:ObjectProperty ;
    rdfs:label "has DTM segment" ;
    rdfs:comment "Relates an InvoiceMessage to its DTMSegment(s)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :DTMSegment ;
    owl:inverseOf :isDTMSegmentOf .

:isDTMSegmentOf a owl:ObjectProperty ;
    rdfs:label "is DTM segment of" ;
    rdfs:comment "A DTMSegment is part of an InvoiceMessage. Inverse of hasDTMSegment." ;
    rdfs:domain :DTMSegment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasDTMSegment .

:hasMOASegment a owl:ObjectProperty ;
    rdfs:label "has MOA segment" ;
    rdfs:comment "Relates an InvoiceMessage to its MOASegment(s)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :MOASegment ;
    owl:inverseOf :isMOASegmentOf .

:isMOASegmentOf a owl:ObjectProperty ;
    rdfs:label "is MOA segment of" ;
    rdfs:comment "A MOASegment is part of an InvoiceMessage. Inverse of hasMOASegment." ;
    rdfs:domain :MOASegment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasMOASegment .

:hasQTYSegment a owl:ObjectProperty ;
    rdfs:label "has QTY segment" ;
    rdfs:comment "Relates an InvoiceMessage to its QTYSegment(s)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :QTYSegment ;
    owl:inverseOf :isQTYSegmentOf .

:isQTYSegmentOf a owl:ObjectProperty ;
    rdfs:label "is QTY segment of" ;
    rdfs:comment "A QTYSegment is part of an InvoiceMessage. Inverse of hasQTYSegment." ;
    rdfs:domain :QTYSegment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasQTYSegment .

:hasMEASegment a owl:ObjectProperty ;
    rdfs:label "has MEA segment" ;
    rdfs:comment "Relates an InvoiceMessage to its MEASegment(s)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :MEASegment ;
    owl:inverseOf :isMEASegmentOf .

:isMEASegmentOf a owl:ObjectProperty ;
    rdfs:label "is MEA segment of" ;
    rdfs:comment "A MEASegment is part of an InvoiceMessage. Inverse of hasMEASegment." ;
    rdfs:domain :MEASegment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasMEASegment .

:hasALCSegment a owl:ObjectProperty ;
    rdfs:label "has ALC segment" ;
    rdfs:comment "Relates an InvoiceMessage to its ALCSegment(s)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ALCSegment ;
    owl:inverseOf :isALCSegmentOf .

:isALCSegmentOf a owl:ObjectProperty ;
    rdfs:label "is ALC segment of" ;
    rdfs:comment "An ALCSegment is part of an InvoiceMessage. Inverse of hasALCSegment." ;
    rdfs:domain :ALCSegment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasALCSegment .

:hasTAXSegment a owl:ObjectProperty ;
    rdfs:label "has TAX segment" ;
    rdfs:comment "Relates an InvoiceMessage to its TAXSegment(s)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :TAXSegment ;
    owl:inverseOf :isTAXSegmentOf .

:isTAXSegmentOf a owl:ObjectProperty ;
    rdfs:label "is TAX segment of" ;
    rdfs:comment "A TAXSegment is part of an InvoiceMessage. Inverse of hasTAXSegment." ;
    rdfs:domain :TAXSegment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasTAXSegment .

:hasRFFSegment a owl:ObjectProperty ;
    rdfs:label "has RFF segment" ;
    rdfs:comment "Relates an InvoiceMessage to its RFFSegment(s)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :RFFSegment ;
    owl:inverseOf :isRFFSegmentOf .

:isRFFSegmentOf a owl:ObjectProperty ;
    rdfs:label "is RFF segment of" ;
    rdfs:comment "An RFFSegment is part of an InvoiceMessage. Inverse of hasRFFSegment." ;
    rdfs:domain :RFFSegment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasRFFSegment .

#################################################################
# DATA PROPERTIES
#################################################################

:hasGlobalLocationNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has Global Location Number" ;
    rdfs:comment "Relates an Organization to its GLN identifier." ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string .

:hasReferenceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has reference number" ;
    rdfs:comment "Relates a HeaderSection to its reference number." ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string .

:hasDocumentDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has document date" ;
    rdfs:comment "Relates a HeaderSection to its document date (as string, ISO-8601)." ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string .

:hasInvoiceAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "Relates a SummarySection to the invoice total amount." ;
    rdfs:domain :SummarySection ;
    rdfs:range xsd:decimal .

:hasTaxAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has tax amount" ;
    rdfs:comment "Relates a SummarySection to the total tax amount." ;
    rdfs:domain :SummarySection ;
    rdfs:range xsd:decimal .

:hasInvoiceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has invoice number" ;
    rdfs:comment "Relates an InvoiceMessage to its invoice number." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range xsd:string .

:hasNetPrice a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has net price" ;
    rdfs:comment "Relates an InvoiceLine to the net price of the item." ;
    rdfs:domain :InvoiceLine ;
    rdfs:range xsd:decimal .

:hasQuantity a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has quantity" ;
    rdfs:comment "Relates an InvoiceLine to the quantity of the item." ;
    rdfs:domain :InvoiceLine ;
    rdfs:range xsd:integer .

#################################################################
# COMPLEX AXIOMS & RESTRICTIONS
#################################################################

:InvoiceMessage owl:equivalentClass [
    rdf:type owl:Restriction ;
    owl:onProperty :hasSection ;
    owl:allValuesFrom :CompositeElement
] .

:OrganizationRoleAssignment owl:equivalentClass [
    rdf:type owl:Restriction ;
    owl:onProperty :assignedRole ;
    owl:someValuesFrom :AgentRole
] .

:InvoiceLine owl:equivalentClass [
    rdf:type owl:Restriction ;
    owl:onProperty :hasItem ;
    owl:someValuesFrom :Item
] .

#################################################################
# DISJOINTNESS AXIOMS
#################################################################

:BuyerRole owl:disjointWith :DeliveryPartyRole .
:HeaderSection owl:disjointWith :DetailSection , :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
:Organization owl:disjointWith :Item .
:AgentRole owl:disjointWith :Address .
:DTMSegment owl:disjointWith :MOASegment .
:QTYSegment owl:disjointWith :MEASegment .
:ALCSegment owl:disjointWith :TAXSegment .
:RFFSegment owl:disjointWith :NADSegment .

#################################################################
# ANNOTATIONS
#################################################################

# All classes and properties above have rdfs:label and rdfs:comment as required.

function.arguments:
{"key":"current_owl","value":"@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#EDIFACT_INVOIC_Story>
    a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC Ontology" ;
    rdfs:comment "Ontology for modeling UN/EDIFACT D96A INVOIC messages, segments, and business document semantics for industrial procurement." .

#################################################################
# CLASSES
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "Top-level envelope containing one or more EDIFACT messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A message within an interchange, such as INVOIC." .

:InvoiceMessage a owl:Class ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "A message representing an invoice (INVOIC)." ;
    rdfs:subClassOf :Message .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment is a logical grouping of data elements in EDIFACT." .

:BGM_Segment a owl:Class ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." ;
    rdfs:subClassOf :Segment .

:NADSegment a owl:Class ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment for participant details." ;
    rdfs:subClassOf :Segment .

:DTMSegment a owl:Class ;
    rdfs:label "DTM Segment" ;
    rdfs:comment "Date/Time/Period segment, with subclasses for qualifiers (e.g., 137: Document Date)." ;
    rdfs:subClassOf :Segment .

:MOASegment a owl:Class ;
    rdfs:label "MOA Segment" ;
    rdfs:comment "Monetary Amount segment, for invoice totals, taxes, etc." ;
    rdfs:subClassOf :Segment .

:QTYSegment a owl:Class ;
    rdfs:label "QTY Segment" ;
    rdfs:comment "Quantity segment, with qualifiers (e.g., invoiced quantity)." ;
    rdfs:subClassOf :Segment .

:MEASegment a owl:Class ;
    rdfs:label "MEA Segment" ;
    rdfs:comment "Measurements segment, for reporting measurements relevant to line items." ;
    rdfs:subClassOf :Segment .

:ALCSegment a owl:Class ;
    rdfs:label "ALC Segment" ;
    rdfs:comment "Allowances/Charges segment." ;
    rdfs:subClassOf :Segment .

:TAXSegment a owl:Class ;
    rdfs:label "TAX Segment" ;
    rdfs:comment "Tax details segment, for specifying tax categories, rates, and amounts." ;
    rdfs:subClassOf :Segment .

:RFFSegment a owl:Class ;
    rdfs:label "RFF Segment" ;
    rdfs:comment "Reference segment, used for document and line-level referencing." ;
    rdfs:subClassOf :Segment .

:CompositeElement a owl:Class ;
    rdfs:label "Composite Element" ;
    rdfs:comment "A composite data element in a segment." .

:SimpleElement a owl:Class ;
    rdfs:label "Simple Element" ;
    rdfs:comment "A simple (atomic) data element in a segment or composite." ;
    rdfs:subClassOf :CompositeElement .

:HeaderSection a owl:Class ;
    rdfs:label "Header Section" ;
    rdfs:comment "Section containing document-level data (dates, references, etc.)." ;
    rdfs:subClassOf :CompositeElement .

:DetailSection a owl:Class ;
    rdfs:label "Detail Section" ;
    rdfs:comment "Section containing invoice line items." ;
    rdfs:subClassOf :CompositeElement .

:SummarySection a owl:Class ;
    rdfs:label "Summary Section" ;
    rdfs:comment "Section summarizing totals, taxes, etc." ;
    rdfs:subClassOf :CompositeElement .

:InvoiceLine a owl:Class ;
    rdfs:label "Invoice Line" ;
    rdfs:comment "A single line item in the invoice." ;
    rdfs:subClassOf :DetailSection .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in the invoice, such as buyer or supplier." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the invoice (e.g., Buyer, Delivery Party)." .

:BuyerRole a owl:Class ;
    rdfs:label "Buyer Role" ;
    rdfs:comment "Role of buyer in the invoice." ;
    rdfs:subClassOf :AgentRole .

:DeliveryPartyRole a owl:Class ;
    rdfs:label "Delivery Party Role" ;
    rdfs:comment "Role of delivery party in the invoice." ;
    rdfs:subClassOf :AgentRole .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "Physical or logical address associated with an organization." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "GLN identifier for organization locations." ;
    rdfs:subClassOf :SimpleElement .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "An item being sold in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "Price information for an item." ;
    rdfs:subClassOf :SimpleElement .

:Quantity a owl:Class ;
    rdfs:label "Quantity" ;
    rdfs:comment "Quantity information for an item or line." ;
    rdfs:subClassOf :SimpleElement .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "Tax information related to items or invoice." ;
    rdfs:subClassOf :SimpleElement .

:ReferenceNumber a owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "A reference number (e.g., invoice number, order number)." ;
    rdfs:subClassOf :SimpleElement .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice is assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint used for automated validation of invoice data." .

:P2P_O_Alignment a owl:Class ;
    rdfs:label "P2P-O Alignment" ;
    rdfs:comment "Alignment node for Purchase-to-Pay Ontology." .

:EN16931_Alignment a owl:Class ;
    rdfs:label "EN 16931 Alignment" ;
    rdfs:comment "Alignment node for EN 16931 European Standard." .

:InvoiceAmount a owl:Class ;
    rdfs:label "Invoice Amount" ;
    rdfs:comment "Class for invoice total amount, used for reification if needed." ;
    rdfs:subClassOf :SimpleElement .

:InvoiceNumber a owl:Class ;
    rdfs:label "Invoice Number" ;
    rdfs:comment "Class for invoice number, used for reification if needed." ;
    rdfs:subClassOf :SimpleElement .

# Pivot Classes
:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "Reifies the assignment of a role to an organization within an invoice context." .

:InvoiceLineItemDetail a owl:Class ;
    rdfs:label "Invoice Line Item Detail" ;
    rdfs:comment "Reifies the details of an invoice line item, such as price, quantity, and tax." ;
    rdfs:subClassOf :InvoiceLine .

#################################################################
# OBJECT PROPERTIES
#################################################################

:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Relates an InterchangeEnvelope to its contained Message(s)." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope a owl:ObjectProperty ;
    rdfs:label "is contained in envelope" ;
    rdfs:comment "A Message is contained in an InterchangeEnvelope. Inverse of containsMessage." ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    owl:inverseOf :containsMessage .

:hasSegment a owl:ObjectProperty ;
    rdfs:label "has segment" ;
    rdfs:comment "Relates a Message to its constituent Segments." ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:label "is segment of" ;
    rdfs:comment "A Segment is part of a Message. Inverse of hasSegment." ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    owl:inverseOf :hasSegment .

:hasSection a owl:ObjectProperty ;
    rdfs:label "has section" ;
    rdfs:comment "Relates an InvoiceMessage to its major logical sections (header, detail, summary)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :CompositeElement ;
    owl:inverseOf :isSectionOf .

:isSectionOf a owl:ObjectProperty ;
    rdfs:label "is section of" ;
    rdfs:comment "A CompositeElement is a section of an InvoiceMessage. Inverse of hasSection." ;
    rdfs:domain :CompositeElement ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasSection .

:hasInvoiceLine a owl:ObjectProperty ;
    rdfs:label "has invoice line" ;
    rdfs:comment "Relates a DetailSection to its InvoiceLine(s)." ;
    rdfs:domain :DetailSection ;
    rdfs:range :InvoiceLine ;
    owl:inverseOf :isInvoiceLineOf .

:isInvoiceLineOf a owl:ObjectProperty ;
    rdfs:label "is invoice line of" ;
    rdfs:comment "An InvoiceLine is part of a DetailSection. Inverse of hasInvoiceLine." ;
    rdfs:domain :InvoiceLine ;
    rdfs:range :DetailSection ;
    owl:inverseOf :hasInvoiceLine .

:hasItem a owl:ObjectProperty ;
    rdfs:label "has item" ;
    rdfs:comment "Relates an InvoiceLine to the Item being sold." ;
    rdfs:domain :InvoiceLine ;
    rdfs:range :Item ;
    owl:inverseOf :isItemOfInvoiceLine .

:isItemOfInvoiceLine a owl:ObjectProperty ;
    rdfs:label "is item of invoice line" ;
    rdfs:comment "An Item is part of an InvoiceLine. Inverse of hasItem." ;
    rdfs:domain :Item ;
    rdfs:range :InvoiceLine ;
    owl:inverseOf :hasItem .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Relates an Organization to its OrganizationRoleAssignment(s)." ;
    rdfs:domain :Organization ;
    rdfs:range :OrganizationRoleAssignment ;
    owl:inverseOf :isRoleAssignmentOf .

:isRoleAssignmentOf a owl:ObjectProperty ;
    rdfs:label "is role assignment of" ;
    rdfs:comment "An OrganizationRoleAssignment is for an Organization. Inverse of hasRoleAssignment." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Organization ;
    owl:inverseOf :hasRoleAssignment .

:assignedRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "assigned role" ;
    rdfs:comment "Relates an OrganizationRoleAssignment to the AgentRole." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :AgentRole ;
    owl:inverseOf :isRoleAssignedTo .

:isRoleAssignedTo a owl:ObjectProperty ;
    rdfs:label "is role assigned to" ;
    rdfs:comment "An AgentRole is assigned to an OrganizationRoleAssignment. Inverse of assignedRole." ;
    rdfs:domain :AgentRole ;
    rdfs:range :OrganizationRoleAssignment ;
    owl:inverseOf :assignedRole .

:assignedToInvoice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "assigned to invoice" ;
    rdfs:comment "Relates an OrganizationRoleAssignment to the InvoiceMessage context." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasRoleAssignmentInInvoice .

:hasRoleAssignmentInInvoice a owl:ObjectProperty ;
    rdfs:label "has role assignment in invoice" ;
    rdfs:comment "An InvoiceMessage has a role assignment. Inverse of assignedToInvoice." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :OrganizationRoleAssignment ;
    owl:inverseOf :assignedToInvoice .

:hasAddress a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has address" ;
    rdfs:comment "Relates an Organization to its Address." ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    owl:inverseOf :isAddressOf .

:isAddressOf a owl:ObjectProperty ;
    rdfs:label "is address of" ;
    rdfs:comment "An Address belongs to an Organization. Inverse of hasAddress." ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    owl:inverseOf :hasAddress .

:hasBusinessProcess a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has business process" ;
    rdfs:comment "Relates an InvoiceMessage to a BusinessProcess." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    owl:inverseOf :isBusinessProcessOf .

:isBusinessProcessOf a owl:ObjectProperty ;
    rdfs:label "is business process of" ;
    rdfs:comment "A BusinessProcess relates to an InvoiceMessage. Inverse of hasBusinessProcess." ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasBusinessProcess .

:isAlignedWithP2P_O a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "is aligned with P2P-O" ;
    rdfs:comment "Relates an InvoiceMessage to a P2P_O_Alignment node." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :P2P_O_Alignment ;
    owl:inverseOf :alignsP2POToInvoice .

:alignsP2POToInvoice a owl:ObjectProperty ;
    rdfs:label "aligns P2P-O to invoice" ;
    rdfs:comment "A P2P_O_Alignment aligns to an InvoiceMessage. Inverse of isAlignedWithP2P_O." ;
    rdfs:domain :P2P_O_Alignment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :isAlignedWithP2P_O .

:isAlignedWithEN16931 a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "is aligned with EN16931" ;
    rdfs:comment "Relates an InvoiceMessage to an EN16931_Alignment node." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :EN16931_Alignment ;
    owl:inverseOf :alignsEN16931ToInvoice .

:alignsEN16931ToInvoice a owl:ObjectProperty ;
    rdfs:label "aligns EN16931 to invoice" ;
    rdfs:comment "An EN16931_Alignment aligns to an InvoiceMessage. Inverse of isAlignedWithEN16931." ;
    rdfs:domain :EN16931_Alignment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :isAlignedWithEN16931 .

:hasValidationConstraint a owl:ObjectProperty ;
    rdfs:label "has validation constraint" ;
    rdfs:comment "Relates an InvoiceMessage to a ValidationConstraint." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ValidationConstraint ;
    owl:inverseOf :isValidationConstraintOf .

:isValidationConstraintOf a owl:ObjectProperty ;
    rdfs:label "is validation constraint of" ;
    rdfs:comment "A ValidationConstraint is for an InvoiceMessage. Inverse of hasValidationConstraint." ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasValidationConstraint .

:hasDTMSegment a owl:ObjectProperty ;
    rdfs:label "has DTM segment" ;
    rdfs:comment "Relates an InvoiceMessage to its DTMSegment(s)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :DTMSegment ;
    owl:inverseOf :isDTMSegmentOf .

:isDTMSegmentOf a owl:ObjectProperty ;
    rdfs:label "is DTM segment of" ;
    rdfs:comment "A DTMSegment is part of an InvoiceMessage. Inverse of hasDTMSegment." ;
    rdfs:domain :DTMSegment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasDTMSegment .

:hasMOASegment a owl:ObjectProperty ;
    rdfs:label "has MOA segment" ;
    rdfs:comment "Relates an InvoiceMessage to its MOASegment(s)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :MOASegment ;
    owl:inverseOf :isMOASegmentOf .

:isMOASegmentOf a owl:ObjectProperty ;
    rdfs:label "is MOA segment of" ;
    rdfs:comment "A MOASegment is part of an InvoiceMessage. Inverse of hasMOASegment." ;
    rdfs:domain :MOASegment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasMOASegment .

:hasQTYSegment a owl:ObjectProperty ;
    rdfs:label "has QTY segment" ;
    rdfs:comment "Relates an InvoiceMessage to its QTYSegment(s)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :QTYSegment ;
    owl:inverseOf :isQTYSegmentOf .

:isQTYSegmentOf a owl:ObjectProperty ;
    rdfs:label "is QTY segment of" ;
    rdfs:comment "A QTYSegment is part of an InvoiceMessage. Inverse of hasQTYSegment." ;
    rdfs:domain :QTYSegment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasQTYSegment .

:hasMEASegment a owl:ObjectProperty ;
    rdfs:label "has MEA segment" ;
    rdfs:comment "Relates an InvoiceMessage to its MEASegment(s)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :MEASegment ;
    owl:inverseOf :isMEASegmentOf .

:isMEASegmentOf a owl:ObjectProperty ;
    rdfs:label "is MEA segment of" ;
    rdfs:comment "A MEASegment is part of an InvoiceMessage. Inverse of hasMEASegment." ;
    rdfs:domain :MEASegment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasMEASegment .

:hasALCSegment a owl:ObjectProperty ;
    rdfs:label "has ALC segment" ;
    rdfs:comment "Relates an InvoiceMessage to its ALCSegment(s)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ALCSegment ;
    owl:inverseOf :isALCSegmentOf .

:isALCSegmentOf a owl:ObjectProperty ;
    rdfs:label "is ALC segment of" ;
    rdfs:comment "An ALCSegment is part of an InvoiceMessage. Inverse of hasALCSegment." ;
    rdfs:domain :ALCSegment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasALCSegment .

:hasTAXSegment a owl:ObjectProperty ;
    rdfs:label "has TAX segment" ;
    rdfs:comment "Relates an InvoiceMessage to its TAXSegment(s)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :TAXSegment ;
    owl:inverseOf :isTAXSegmentOf .

:isTAXSegmentOf a owl:ObjectProperty ;
    rdfs:label "is TAX segment of" ;
    rdfs:comment "A TAXSegment is part of an InvoiceMessage. Inverse of hasTAXSegment." ;
    rdfs:domain :TAXSegment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasTAXSegment .

:hasRFFSegment a owl:ObjectProperty ;
    rdfs:label "has RFF segment" ;
    rdfs:comment "Relates an InvoiceMessage to its RFFSegment(s)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :RFFSegment ;
    owl:inverseOf :isRFFSegmentOf .

:isRFFSegmentOf a owl:ObjectProperty ;
    rdfs:label "is RFF segment of" ;
    rdfs:comment "An RFFSegment is part of an InvoiceMessage. Inverse of hasRFFSegment." ;
    rdfs:domain :RFFSegment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasRFFSegment .

#################################################################
# DATA PROPERTIES
#################################################################

:hasGlobalLocationNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has Global Location Number" ;
    rdfs:comment "Relates an Organization to its GLN identifier." ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string .

:hasReferenceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has reference number" ;
    rdfs:comment "Relates a HeaderSection to its reference number." ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string .

:hasDocumentDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has document date" ;
    rdfs:comment "Relates a HeaderSection to its document date (as string, ISO-8601)." ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string .

:hasInvoiceAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "Relates a SummarySection to the invoice total amount." ;
    rdfs:domain :SummarySection ;
    rdfs:range xsd:decimal .

:hasTaxAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has tax amount" ;
    rdfs:comment "Relates a SummarySection to the total tax amount." ;
    rdfs:domain :SummarySection ;
    rdfs:range xsd:decimal .

:hasInvoiceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has invoice number" ;
    rdfs:comment "Relates an InvoiceMessage to its invoice number." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range xsd:string .

:hasNetPrice a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has net price" ;
    rdfs:comment "Relates an InvoiceLine to the net price of the item." ;
    rdfs:domain :InvoiceLine ;
    rdfs:range xsd:decimal .

:hasQuantity a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has quantity" ;
    rdfs:comment "Relates an InvoiceLine to the quantity of the item." ;
    rdfs:domain :InvoiceLine ;
    rdfs:range xsd:integer .

#################################################################
# COMPLEX AXIOMS & RESTRICTIONS
#################################################################

:InvoiceMessage owl:equivalentClass [
    rdf:type owl:Restriction ;
    owl:onProperty :hasSection ;
    owl:allValuesFrom :CompositeElement
] .

:OrganizationRoleAssignment owl:equivalentClass [
    rdf:type owl:Restriction ;
    owl:onProperty :assignedRole ;
    owl:someValuesFrom :AgentRole
] .

:InvoiceLine owl:equivalentClass [
    rdf:type owl:Restriction ;
    owl:onProperty :hasItem ;
    owl:someValuesFrom :Item
] .

#################################################################
# DISJOINTNESS AXIOMS
#################################################################

:BuyerRole owl:disjointWith :DeliveryPartyRole .
:HeaderSection owl:disjointWith :DetailSection , :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
:Organization owl:disjointWith :Item .
:AgentRole owl:disjointWith :Address .
:DTMSegment owl:disjointWith :MOASegment .
:QTYSegment owl:disjointWith :MEASegment .
:ALCSegment owl:disjointWith :TAXSegment .
:RFFSegment owl:disjointWith :NADSegment .

#################################################################
# ANNOTATIONS
#################################################################

# All classes and properties above have rdfs:label and rdfs:comment as required.
"}

args.owl_content:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#EDIFACT_INVOIC_Story>
    a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC Ontology" ;
    rdfs:comment "Ontology for modeling UN/EDIFACT D96A INVOIC messages, segments, and business document semantics for industrial procurement." .

#################################################################
# CLASSES
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "Top-level envelope containing one or more EDIFACT messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A message within an interchange, such as INVOIC." .

:InvoiceMessage a owl:Class ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "A message representing an invoice (INVOIC)." ;
    rdfs:subClassOf :Message .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment is a logical grouping of data elements in EDIFACT." .

:BGM_Segment a owl:Class ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." ;
    rdfs:subClassOf :Segment .

:NADSegment a owl:Class ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment for participant details." ;
    rdfs:subClassOf :Segment .

:DTMSegment a owl:Class ;
    rdfs:label "DTM Segment" ;
    rdfs:comment "Date/Time/Period segment, with subclasses for qualifiers (e.g., 137: Document Date)." ;
    rdfs:subClassOf :Segment .

:MOASegment a owl:Class ;
    rdfs:label "MOA Segment" ;
    rdfs:comment "Monetary Amount segment, for invoice totals, taxes, etc." ;
    rdfs:subClassOf :Segment .

:QTYSegment a owl:Class ;
    rdfs:label "QTY Segment" ;
    rdfs:comment "Quantity segment, with qualifiers (e.g., invoiced quantity)." ;
    rdfs:subClassOf :Segment .

:MEASegment a owl:Class ;
    rdfs:label "MEA Segment" ;
    rdfs:comment "Measurements segment, for reporting measurements relevant to line items." ;
    rdfs:subClassOf :Segment .

:ALCSegment a owl:Class ;
    rdfs:label "ALC Segment" ;
    rdfs:comment "Allowances/Charges segment." ;
    rdfs:subClassOf :Segment .

:TAXSegment a owl:Class ;
    rdfs:label "TAX Segment" ;
    rdfs:comment "Tax details segment, for specifying tax categories, rates, and amounts." ;
    rdfs:subClassOf :Segment .

:RFFSegment a owl:Class ;
    rdfs:label "RFF Segment" ;
    rdfs:comment "Reference segment, used for document and line-level referencing." ;
    rdfs:subClassOf :Segment .

:CompositeElement a owl:Class ;
    rdfs:label "Composite Element" ;
    rdfs:comment "A composite data element in a segment." .

:SimpleElement a owl:Class ;
    rdfs:label "Simple Element" ;
    rdfs:comment "A simple (atomic) data element in a segment or composite." ;
    rdfs:subClassOf :CompositeElement .

:HeaderSection a owl:Class ;
    rdfs:label "Header Section" ;
    rdfs:comment "Section containing document-level data (dates, references, etc.)." ;
    rdfs:subClassOf :CompositeElement .

:DetailSection a owl:Class ;
    rdfs:label "Detail Section" ;
    rdfs:comment "Section containing invoice line items." ;
    rdfs:subClassOf :CompositeElement .

:SummarySection a owl:Class ;
    rdfs:label "Summary Section" ;
    rdfs:comment "Section summarizing totals, taxes, etc." ;
    rdfs:subClassOf :CompositeElement .

:InvoiceLine a owl:Class ;
    rdfs:label "Invoice Line" ;
    rdfs:comment "A single line item in the invoice." ;
    rdfs:subClassOf :DetailSection .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in the invoice, such as buyer or supplier." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the invoice (e.g., Buyer, Delivery Party)." .

:BuyerRole a owl:Class ;
    rdfs:label "Buyer Role" ;
    rdfs:comment "Role of buyer in the invoice." ;
    rdfs:subClassOf :AgentRole .

:DeliveryPartyRole a owl:Class ;
    rdfs:label "Delivery Party Role" ;
    rdfs:comment "Role of delivery party in the invoice." ;
    rdfs:subClassOf :AgentRole .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "Physical or logical address associated with an organization." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "GLN identifier for organization locations." ;
    rdfs:subClassOf :SimpleElement .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "An item being sold in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "Price information for an item." ;
    rdfs:subClassOf :SimpleElement .

:Quantity a owl:Class ;
    rdfs:label "Quantity" ;
    rdfs:comment "Quantity information for an item or line." ;
    rdfs:subClassOf :SimpleElement .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "Tax information related to items or invoice." ;
    rdfs:subClassOf :SimpleElement .

:ReferenceNumber a owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "A reference number (e.g., invoice number, order number)." ;
    rdfs:subClassOf :SimpleElement .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice is assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint used for automated validation of invoice data." .

:P2P_O_Alignment a owl:Class ;
    rdfs:label "P2P-O Alignment" ;
    rdfs:comment "Alignment node for Purchase-to-Pay Ontology." .

:EN16931_Alignment a owl:Class ;
    rdfs:label "EN 16931 Alignment" ;
    rdfs:comment "Alignment node for EN 16931 European Standard." .

:InvoiceAmount a owl:Class ;
    rdfs:label "Invoice Amount" ;
    rdfs:comment "Class for invoice total amount, used for reification if needed." ;
    rdfs:subClassOf :SimpleElement .

:InvoiceNumber a owl:Class ;
    rdfs:label "Invoice Number" ;
    rdfs:comment "Class for invoice number, used for reification if needed." ;
    rdfs:subClassOf :SimpleElement .

# Pivot Classes
:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "Reifies the assignment of a role to an organization within an invoice context." .

:InvoiceLineItemDetail a owl:Class ;
    rdfs:label "Invoice Line Item Detail" ;
    rdfs:comment "Reifies the details of an invoice line item, such as price, quantity, and tax." ;
    rdfs:subClassOf :InvoiceLine .

#################################################################
# OBJECT PROPERTIES
#################################################################

:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Relates an InterchangeEnvelope to its contained Message(s)." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope a owl:ObjectProperty ;
    rdfs:label "is contained in envelope" ;
    rdfs:comment "A Message is contained in an InterchangeEnvelope. Inverse of containsMessage." ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
