args.value:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#EDIFACT_INVOIC_Story>
    a owl:Ontology ;
    rdfs:label "EDIFACT INVOIC Ontology" ;
    rdfs:comment "Ontology for modeling UN/EDIFACT D96A INVOIC messages, segments, and business document semantics for industrial procurement." .

#################################################################
# CLASSES
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "Top-level envelope containing one or more EDIFACT messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A message within an interchange, such as INVOIC." .

:InvoiceMessage a owl:Class ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "A message representing an invoice (INVOIC)." ;
    rdfs:subClassOf :Message .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment is a logical grouping of data elements in EDIFACT." .

:BGMSegment a owl:Class ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." ;
    rdfs:subClassOf :Segment .

:NADSegment a owl:Class ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment for participant details." ;
    rdfs:subClassOf :Segment .

:DTMSegment a owl:Class ;
    rdfs:label "DTM Segment" ;
    rdfs:comment "Date/Time/Period segment, with subclasses for qualifiers (e.g., 137: Document Date)." ;
    rdfs:subClassOf :Segment .

:MOASegment a owl:Class ;
    rdfs:label "MOA Segment" ;
    rdfs:comment "Monetary Amount segment, for invoice totals, taxes, etc." ;
    rdfs:subClassOf :Segment .

:QTYSegment a owl:Class ;
    rdfs:label "QTY Segment" ;
    rdfs:comment "Quantity segment, with qualifiers (e.g., invoiced quantity)." ;
    rdfs:subClassOf :Segment .

:MEASegment a owl:Class ;
    rdfs:label "MEA Segment" ;
    rdfs:comment "Measurements segment, for reporting measurements relevant to line items." ;
    rdfs:subClassOf :Segment .

:ALCSegment a owl:Class ;
    rdfs:label "ALC Segment" ;
    rdfs:comment "Allowances/Charges segment." ;
    rdfs:subClassOf :Segment .

:TAXSegment a owl:Class ;
    rdfs:label "TAX Segment" ;
    rdfs:comment "Tax details segment, for specifying tax categories, rates, and amounts." ;
    rdfs:subClassOf :Segment .

:RFFSegment a owl:Class ;
    rdfs:label "RFF Segment" ;
    rdfs:comment "Reference segment, used for document and line-level referencing." ;
    rdfs:subClassOf :Segment .

:CompositeElement a owl:Class ;
    rdfs:label "Composite Element" ;
    rdfs:comment "A composite data element in a segment." .

:SimpleElement a owl:Class ;
    rdfs:label "Simple Element" ;
    rdfs:comment "A simple (atomic) data element in a segment or composite." ;
    rdfs:subClassOf :CompositeElement .

:HeaderSection a owl:Class ;
    rdfs:label "Header Section" ;
    rdfs:comment "Section containing document-level data (dates, references, etc.)." ;
    rdfs:subClassOf :CompositeElement .

:DetailSection a owl:Class ;
    rdfs:label "Detail Section" ;
    rdfs:comment "Section containing invoice line items." ;
    rdfs:subClassOf :CompositeElement .

:SummarySection a owl:Class ;
    rdfs:label "Summary Section" ;
    rdfs:comment "Section summarizing totals, taxes, etc." ;
    rdfs:subClassOf :CompositeElement .

:InvoiceLine a owl:Class ;
    rdfs:label "Invoice Line" ;
    rdfs:comment "A single line item in the invoice." ;
    rdfs:subClassOf :DetailSection .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in the invoice, such as buyer or supplier." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the invoice (e.g., Buyer, Delivery Party)." .

:BuyerRole a owl:Class ;
    rdfs:label "Buyer Role" ;
    rdfs:comment "Role of buyer in the invoice." ;
    rdfs:subClassOf :AgentRole .

:DeliveryPartyRole a owl:Class ;
    rdfs:label "Delivery Party Role" ;
    rdfs:comment "Role of delivery party in the invoice." ;
    rdfs:subClassOf :AgentRole .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "Physical or logical address associated with an organization." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "GLN identifier for organization locations." ;
    rdfs:subClassOf :SimpleElement .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "An item being sold in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "Price information for an item." ;
    rdfs:subClassOf :SimpleElement .

:Quantity a owl:Class ;
    rdfs:label "Quantity" ;
    rdfs:comment "Quantity information for an item or line." ;
    rdfs:subClassOf :SimpleElement .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "Tax information related to items or invoice." ;
    rdfs:subClassOf :SimpleElement .

:ReferenceNumber a owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "A reference number (e.g., invoice number, order number)." ;
    rdfs:subClassOf :SimpleElement .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice is assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint used for automated validation of invoice data." .

:P2POAlignment a owl:Class ;
    rdfs:label "P2P-O Alignment" ;
    rdfs:comment "Alignment node for Purchase-to-Pay Ontology." .

:EN16931Alignment a owl:Class ;
    rdfs:label "EN 16931 Alignment" ;
    rdfs:comment "Alignment node for EN 16931 European Standard." .

:InvoiceAmount a owl:Class ;
    rdfs:label "Invoice Amount" ;
    rdfs:comment "Class for invoice total amount, used for reification if needed." ;
    rdfs:subClassOf :SimpleElement .

:InvoiceNumber a owl:Class ;
    rdfs:label "Invoice Number" ;
    rdfs:comment "Class for invoice number, used for reification if needed." ;
    rdfs:subClassOf :SimpleElement .

# Pivot Classes
:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "Reifies the assignment of a role to an organization within an invoice context." .

:InvoiceLineItemDetail a owl:Class ;
    rdfs:label "Invoice Line Item Detail" ;
    rdfs:comment "Reifies the details of an invoice line item, such as price, quantity, and tax." ;
    rdfs:subClassOf :InvoiceLine .

#################################################################
# OBJECT PROPERTIES
#################################################################

:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Relates an InterchangeEnvelope to its contained Message(s)." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope a owl:ObjectProperty ;
    rdfs:label "is contained in envelope" ;
    rdfs:comment "A Message is contained in an InterchangeEnvelope. Inverse of containsMessage." ;
    rdfs:domain :Message ;
