    rdfs:comment "Relates an InvoiceMessage to its QTYSegment(s)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :QTYSegment ;
    owl:inverseOf :isQTYSegmentOf .

:isQTYSegmentOf a owl:ObjectProperty ;
    rdfs:label "is QTY segment of" ;
    rdfs:comment "A QTYSegment is part of an InvoiceMessage. Inverse of hasQTYSegment." ;
    rdfs:domain :QTYSegment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasQTYSegment .

:hasMEASegment a owl:ObjectProperty ;
    rdfs:label "has MEA segment" ;
    rdfs:comment "Relates an InvoiceMessage to its MEASegment(s)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :MEASegment ;
    owl:inverseOf :isMEASegmentOf .

:isMEASegmentOf a owl:ObjectProperty ;
    rdfs:label "is MEA segment of" ;
    rdfs:comment "A MEASegment is part of an InvoiceMessage. Inverse of hasMEASegment." ;
    rdfs:domain :MEASegment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasMEASegment .

:hasALCSegment a owl:ObjectProperty ;
    rdfs:label "has ALC segment" ;
    rdfs:comment "Relates an InvoiceMessage to its ALCSegment(s)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ALCSegment ;
    owl:inverseOf :isALCSegmentOf .

:isALCSegmentOf a owl:ObjectProperty ;
    rdfs:label "is ALC segment of" ;
    rdfs:comment "An ALCSegment is part of an InvoiceMessage. Inverse of hasALCSegment." ;
    rdfs:domain :ALCSegment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasALCSegment .

