#################################################################
# DATA PROPERTIES
#################################################################

:hasGlobalLocationNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has Global Location Number" ;
    rdfs:comment "Relates an Organization to its GLN identifier." ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string .

:hasReferenceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has reference number" ;
    rdfs:comment "Relates a HeaderSection to its reference number." ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string .

:hasDocumentDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has document date" ;
    rdfs:comment "Relates a HeaderSection to its document date (as string, ISO-8601)." ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string .

:hasInvoiceAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "Relates a SummarySection to the invoice total amount." ;
    rdfs:domain :SummarySection ;
    rdfs:range xsd:decimal .

:hasTaxAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has tax amount" ;
    rdfs:comment "Relates a SummarySection to the total tax amount." ;
    rdfs:domain :SummarySection ;
    rdfs:range xsd:decimal .

:hasInvoiceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has invoice number" ;
    rdfs:comment "Relates an InvoiceMessage to its invoice number." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range xsd:string .

:hasNetPrice a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has net price" ;
    rdfs:comment "Relates an InvoiceLine to the net price of the item." ;
    rdfs:domain :InvoiceLine ;
    rdfs:range xsd:decimal .

:hasQuantity a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has quantity" ;
    rdfs:comment "Relates an InvoiceLine to the quantity of the item." ;
    rdfs:domain :InvoiceLine ;
    rdfs:range xsd:integer .

#################################################################
# COMPLEX AXIOMS & RESTRICTIONS
#################################################################

:InvoiceMessage owl:equivalentClass [
    rdf:type owl:Restriction ;
    owl:onProperty :hasSection ;
    owl:allValuesFrom :CompositeElement
] .

:OrganizationRoleAssignment owl:equivalentClass [
    rdf:type owl:Restriction ;
    owl:onProperty :assignedRole ;
    owl:someValuesFrom :AgentRole
] .

:InvoiceLine owl:equivalentClass [
    rdf:type owl:Restriction ;
    owl:onProperty :hasItem ;
    owl:someValuesFrom :Item
] .

#################################################################
# DISJOINTNESS AXIOMS
#################################################################

:BuyerRole owl:disjointWith :DeliveryPartyRole .
:HeaderSection owl:disjointWith :DetailSection , :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
:Organization owl:disjointWith :Item .
:AgentRole owl:disjointWith :Address .
:DTMSegment owl:disjointWith :MOASegment .
:QTYSegment owl:disjointWith :MEASegment .
:ALCSegment owl:disjointWith :TAXSegment .
:RFFSegment owl:disjointWith :NADSegment .

#################################################################
# ANNOTATIONS
#################################################################

