    rdfs:subClassOf :Segment .

:MOA_Segment a owl:Class ;
    rdfs:label "MOA Segment" ;
    rdfs:comment "Monetary Amount segment, for invoice totals, taxes, etc." ;
    rdfs:subClassOf :Segment .

:QTY_Segment a owl:Class ;
    rdfs:label "QTY Segment" ;
    rdfs:comment "Quantity segment, with qualifiers (e.g., invoiced quantity)." ;
