    rdfs:label "message of" ;
    rdfs:comment "Inverse of hasMessage, links a message to its envelope." ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    owl:inverseOf :hasMessage .

:containsSegment rdf:type owl:ObjectProperty ;
    rdfs:label "contains segment" ;
    rdfs:comment "Links a message to its segments." ;
    rdfs:domain :Message ;
    rdfs:range :Segment .

:segmentOf rdf:type owl:ObjectProperty ;
    rdfs:label "segment of" ;
    rdfs:comment "Inverse of containsSegment, links a segment to its parent message." ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    owl:inverseOf :containsSegment .

:hasSection rdf:type owl:ObjectProperty ;
    rdfs:label "has section" ;
    rdfs:comment "Links an invoice message to its sections (header, detail, summary)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Segment .

:sectionOf rdf:type owl:ObjectProperty ;
    rdfs:label "section of" ;
    rdfs:comment "Inverse of hasSection, links a section to its invoice message." ;
    rdfs:domain :Segment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasSection .

:hasHeader rdf:type owl:ObjectProperty ;
    rdfs:label "has header" ;
    rdfs:comment "Links an invoice message to its header section." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :HeaderSection .

:headerOf rdf:type owl:ObjectProperty ;
    rdfs:label "header of" ;
    rdfs:comment "Inverse of hasHeader, links a header section to its invoice message." ;
    rdfs:domain :HeaderSection ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasHeader .

:hasDetail rdf:type owl:ObjectProperty ;
    rdfs:label "has detail" ;
    rdfs:comment "Links an invoice message to its detail section." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :DetailSection .

:detailOf rdf:type owl:ObjectProperty ;
    rdfs:label "detail of" ;
    rdfs:comment "Inverse of hasDetail, links a detail section to its invoice message." ;
    rdfs:domain :DetailSection ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasDetail .

:hasSummary rdf:type owl:ObjectProperty ;
    rdfs:label "has summary" ;
    rdfs:comment "Links an invoice message to its summary section." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :SummarySection .

:summaryOf rdf:type owl:ObjectProperty ;
    rdfs:label "summary of" ;
    rdfs:comment "Inverse of hasSummary, links a summary section to its invoice message." ;
    rdfs:domain :SummarySection ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasSummary .

:hasLineItem rdf:type owl:ObjectProperty ;
    rdfs:label "has line item" ;
    rdfs:comment "Links a detail section to its line items." ;
    rdfs:domain :DetailSection ;
    rdfs:range :LineItem .

:lineItemOf rdf:type owl:ObjectProperty ;
    rdfs:label "line item of" ;
    rdfs:comment "Inverse of hasLineItem, links a line item to its detail section." ;
    rdfs:domain :LineItem ;
    rdfs:range :DetailSection ;
    owl:inverseOf :hasLineItem .

:aboutItem rdf:type owl:ObjectProperty ;
    rdfs:label "about item" ;
    rdfs:comment "Links a line item to the item it describes." ;
    rdfs:domain :LineItem ;
    rdfs:range :Item .

:itemOf rdf:type owl:ObjectProperty ;
    rdfs:label "item of" ;
    rdfs:comment "Inverse of aboutItem, links an item to the line item that describes it." ;
    rdfs:domain :Item ;
    rdfs:range :LineItem ;
    owl:inverseOf :aboutItem .

:hasNetPrice rdf:type owl:ObjectProperty ;
    rdfs:label "has net price" ;
    rdfs:comment "Links a line item to its net price." ;
    rdfs:domain :LineItem ;
    rdfs:range :Price .

:netPriceOf rdf:type owl:ObjectProperty ;
    rdfs:label "net price of" ;
    rdfs:comment "Inverse of hasNetPrice, links a price to its line item." ;
    rdfs:domain :Price ;
    rdfs:range :LineItem ;
    owl:inverseOf :hasNetPrice .

:hasQuantity rdf:type owl:DatatypeProperty ;
    rdfs:label "has quantity" ;
    rdfs:comment "Quantity of items in a line item." ;
    rdfs:domain :LineItem ;
    rdfs:range xsd:decimal .

:hasInvoiceAmount rdf:type owl:ObjectProperty ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "Links a summary section to the invoice amount." ;
    rdfs:domain :SummarySection ;
    rdfs:range :InvoiceAmount .

:invoiceAmountOf rdf:type owl:ObjectProperty ;
    rdfs:label "invoice amount of" ;
    rdfs:comment "Inverse of hasInvoiceAmount, links an invoice amount to its summary section." ;
    rdfs:domain :InvoiceAmount ;
    rdfs:range :SummarySection ;
    owl:inverseOf :hasInvoiceAmount .

:hasTax rdf:type owl:ObjectProperty ;
    rdfs:label "has tax" ;
    rdfs:comment "Links a summary section to the tax applied." ;
    rdfs:domain :SummarySection ;
    rdfs:range :Tax .

:taxOf rdf:type owl:ObjectProperty ;
    rdfs:label "tax of" ;
    rdfs:comment "Inverse of hasTax, links a tax to its summary section." ;
    rdfs:domain :Tax ;
    rdfs:range :SummarySection ;
    owl:inverseOf :hasTax .

:hasOrganizationRoleAssignment rdf:type owl:ObjectProperty ;
    rdfs:label "has organization role assignment" ;
    rdfs:comment "Links an invoice message to a pivot class for organization-role reification." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :OrganizationRoleAssignment .

:organizationRoleAssignmentOf rdf:type owl:ObjectProperty ;
    rdfs:label "organization role assignment of" ;
    rdfs:comment "Inverse of hasOrganizationRoleAssignment, links an organization role assignment to its invoice message." ;
