    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement .

:compositeElementOf rdf:type owl:ObjectProperty ;
    rdfs:label "composite element of" ;
    rdfs:comment "Inverse of hasCompositeElement, links a composite data element to its segment." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    owl:inverseOf :hasCompositeElement .

:hasSimpleElement rdf:type owl:ObjectProperty ;
    rdfs:label "has simple element" ;
    rdfs:comment "Links a composite data element to its simple data elements." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement .

:simpleElementOf rdf:type owl:ObjectProperty ;
    rdfs:label "simple element of" ;
    rdfs:comment "Inverse of hasSimpleElement, links a simple data element to its composite data element." ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    owl:inverseOf :hasSimpleElement .

#################################################################
# PROPERTY CHARACTERISTICS
#################################################################

:hasMessage a owl:FunctionalProperty .
:hasHeader a owl:FunctionalProperty .
:hasDetail a owl:FunctionalProperty .
:hasSummary a owl:FunctionalProperty .

#################################################################
# ANNOTATIONS
#################################################################
# (All classes and properties above include rdfs:label and rdfs:comment)

#################################################################
# COMPLEX AXIOMS & RESTRICTIONS
#################################################################

:InvoiceMessage owl:equivalentClass [ rdf:type owl:Class ; owl:intersectionOf ( [ rdf:type owl:Restriction ; owl:onProperty :hasHeader ; owl:allValuesFrom :HeaderSection ] [ rdf:type owl:Restriction ; owl:onProperty :hasDetail ; owl:allValuesFrom :DetailSection ] [ rdf:type owl:Restriction ; owl:onProperty :hasSummary ; owl:allValuesFrom :SummarySection ] ) ] .

:LineItem owl:equivalentClass [ rdf:type owl:Class ; owl:intersectionOf ( [ rdf:type owl:Restriction ; owl:onProperty :aboutItem ; owl:someValuesFrom :Item ] [ rdf:type owl:Restriction ; owl:onProperty :hasNetPrice ; owl:someValuesFrom :Price ] [ rdf:type owl:Restriction ; owl:onProperty :hasQuantity ; owl:someValuesFrom xsd:decimal ] ) ] .

:OrganizationRoleAssignment owl:equivalentClass [ rdf:type owl:Class ; owl:intersectionOf ( [ rdf:type owl:Restriction ; owl:onProperty :involvesOrganization ; owl:someValuesFrom :Organization ] [ rdf:type owl:Restriction ; owl:onProperty :hasRole ; owl:someValuesFrom :AgentRole ] ) ] .

#################################################################
# INDIVIDUALS (EXAMPLES)
#################################################################
# (No individuals provided; ontology is schema-level)
"}

args.value:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

:EDIFACT_INVOIC_Ontology rdf:type owl:Ontology ;
    rdfs:label "EDIFACT INVOIC Ontology" ;
    rdfs:comment "Ontology for modeling UN/EDIFACT INVOIC messages, segments, roles, and semantic constraints for global trade invoices, with alignment to EN 16931-1 and P2P-O." .

#################################################################
# CLASSES
#################################################################

:InterchangeEnvelope rdf:type owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "Envelope containing one or more EDIFACT messages." .

:Message rdf:type owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message, such as INVOIC." .

:InvoiceMessage rdf:type owl:Class ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "An INVOIC message representing a digital invoice document." ;
    rdfs:subClassOf :Message .

:Segment rdf:type owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment within an EDIFACT message, e.g., BGM or NAD." .

:BGMSegment rdf:type owl:Class ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." ;
    rdfs:subClassOf :Segment .

:NADSegment rdf:type owl:Class ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment for participant details." ;
    rdfs:subClassOf :Segment .

:HeaderSection rdf:type owl:Class ;
    rdfs:label "Header Section" ;
    rdfs:comment "Header section containing document dates and reference numbers." ;
    rdfs:subClassOf :Segment .

:DetailSection rdf:type owl:Class ;
    rdfs:label "Detail Section" ;
    rdfs:comment "Detail section listing individual line items." ;
    rdfs:subClassOf :Segment .

:SummarySection rdf:type owl:Class ;
    rdfs:label "Summary Section" ;
    rdfs:comment "Summary section providing invoice totals and tax amounts." ;
    rdfs:subClassOf :Segment .

:CompositeDataElement rdf:type owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment." .

:SimpleDataElement rdf:type owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite or segment." .

:Organization rdf:type owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An entity involved in the invoice, such as Buyer or Delivery Party." .

:AgentRole rdf:type owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the invoice (e.g., Buyer, Supplier, Delivery Party)." .

:Address rdf:type owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "Address associated with an organization." .

:LineItem rdf:type owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "An itemized product or service in the invoice detail section." .

:Item rdf:type owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service being sold." .

:Price rdf:type owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "Net price of an item." .

:Tax rdf:type owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "Tax amount applied to the invoice." .

:ReferenceNumber rdf:type owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "Invoice number or other reference identifier." .

:BusinessProcess rdf:type owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "Business process to which the invoice is assigned." .

:Identifier rdf:type owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "Generic identifier for organizations or documents." .

:GlobalLocationNumber rdf:type owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "Global Location Number (GLN) for organization identification." ;
    rdfs:subClassOf :Identifier .

:ValidationConstraint rdf:type owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "Constraint for automated validation, e.g., SHACL rules." .

:EN16931Alignment rdf:type owl:Class ;
    rdfs:label "EN 16931 Alignment" ;
    rdfs:comment "Alignment to European Standard EN 16931-1." .

:P2POAlignment rdf:type owl:Class ;
    rdfs:label "P2P-O Alignment" ;
    rdfs:comment "Alignment to Purchase-to-Pay Ontology (P2P-O)." .

:InvoiceAmount rdf:type owl:Class ;
    rdfs:label "Invoice Amount" ;
    rdfs:comment "Total amount of the invoice." .

:OrganizationRoleAssignment rdf:type owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "Pivot class for reifying the relationship between an organization and its role in an invoice." .

#################################################################
# HIERARCHY AND DISJOINTNESS
#################################################################

:HeaderSection owl:disjointWith :DetailSection, :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
:Organization owl:disjointWith :Address .
:AgentRole owl:disjointWith :Organization .

:Segment owl:disjointUnionOf (:BGMSegment :NADSegment :HeaderSection :DetailSection :SummarySection) .

#################################################################
# PROPERTIES
#################################################################

:hasMessage rdf:type owl:ObjectProperty ;
    rdfs:label "has message" ;
    rdfs:comment "Links an interchange envelope to its contained message." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message .

:messageOf rdf:type owl:ObjectProperty ;
    rdfs:label "message of" ;
    rdfs:comment "Inverse of hasMessage, links a message to its envelope." ;
