    rdfs:comment "Links an invoice message to a pivot class for organization-role reification." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :OrganizationRoleAssignment .

:organizationRoleAssignmentOf rdf:type owl:ObjectProperty ;
    rdfs:label "organization role assignment of" ;
    rdfs:comment "Inverse of hasOrganizationRoleAssignment, links an organization role assignment to its invoice message." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasOrganizationRoleAssignment .

:involvesOrganization rdf:type owl:ObjectProperty ;
    rdfs:label "involves organization" ;
    rdfs:comment "Links an organization role assignment to the involved organization." ;
    rdfs:domain :OrganizationRoleAssignment ;
