    rdfs:range :AgentRole .

:roleOfAssignment rdf:type owl:ObjectProperty ;
    rdfs:label "role of assignment" ;
    rdfs:comment "Inverse of hasRole, links an agent role to its assignments." ;
    rdfs:domain :AgentRole ;
    rdfs:range :OrganizationRoleAssignment ;
    owl:inverseOf :hasRole .

:hasAddress rdf:type owl:ObjectProperty ;
    rdfs:label "has address" ;
    rdfs:comment "Links an organization to its address." ;
    rdfs:domain :Organization ;
    rdfs:range :Address .

:addressOf rdf:type owl:ObjectProperty ;
    rdfs:label "address of" ;
    rdfs:comment "Inverse of hasAddress, links an address to its organization." ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    owl:inverseOf :hasAddress .

:hasIdentifier rdf:type owl:ObjectProperty ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links an organization to its identifiers." ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier .

:identifierOf rdf:type owl:ObjectProperty ;
    rdfs:label "identifier of" ;
    rdfs:comment "Inverse of hasIdentifier, links an identifier to its organization." ;
    rdfs:domain :Identifier ;
    rdfs:range :Organization ;
    owl:inverseOf :hasIdentifier .

:hasGlobalLocationNumber rdf:type owl:ObjectProperty ;
    rdfs:label "has global location number" ;
    rdfs:comment "Links an organization to its Global Location Number." ;
    rdfs:domain :Organization ;
    rdfs:range :GlobalLocationNumber .

:globalLocationNumberOf rdf:type owl:ObjectProperty ;
    rdfs:label "global location number of" ;
    rdfs:comment "Inverse of hasGlobalLocationNumber, links a GLN to its organization." ;
    rdfs:domain :GlobalLocationNumber ;
    rdfs:range :Organization ;
    owl:inverseOf :hasGlobalLocationNumber .

:hasReferenceNumber rdf:type owl:ObjectProperty ;
    rdfs:label "has reference number" ;
    rdfs:comment "Links a header section to its reference number." ;
    rdfs:domain :HeaderSection ;
    rdfs:range :ReferenceNumber .

:referenceNumberOf rdf:type owl:ObjectProperty ;
    rdfs:label "reference number of" ;
    rdfs:comment "Inverse of hasReferenceNumber, links a reference number to its header section." ;
    rdfs:domain :ReferenceNumber ;
    rdfs:range :HeaderSection ;
    owl:inverseOf :hasReferenceNumber .

:hasDocumentDate rdf:type owl:DatatypeProperty ;
    rdfs:label "has document date" ;
    rdfs:comment "Date of the invoice document (string format)." ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string .

:isAlignedWithEN16931 rdf:type owl:ObjectProperty ;
    rdfs:label "is aligned with EN 16931" ;
    rdfs:comment "Links an invoice message to EN 16931 alignment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :EN16931Alignment .

:alignedEN16931Of rdf:type owl:ObjectProperty ;
    rdfs:label "aligned EN 16931 of" ;
    rdfs:comment "Inverse of isAlignedWithEN16931, links EN 16931 alignment to its invoice message." ;
    rdfs:domain :EN16931Alignment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :isAlignedWithEN16931 .

:isAlignedWithP2PO rdf:type owl:ObjectProperty ;
    rdfs:label "is aligned with P2P-O" ;
    rdfs:comment "Links an invoice message to P2P-O alignment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :P2POAlignment .

:alignedP2POOf rdf:type owl:ObjectProperty ;
    rdfs:label "aligned P2P-O of" ;
    rdfs:comment "Inverse of isAlignedWithP2PO, links P2P-O alignment to its invoice message." ;
    rdfs:domain :P2POAlignment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :isAlignedWithP2PO .

:validatesWith rdf:type owl:ObjectProperty ;
    rdfs:label "validates with" ;
    rdfs:comment "Links an invoice message to its validation constraints (e.g., SHACL)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ValidationConstraint .

:validatedBy rdf:type owl:ObjectProperty ;
    rdfs:label "validated by" ;
    rdfs:comment "Inverse of validatesWith, links a validation constraint to its invoice message." ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :validatesWith .

:assignedToProcess rdf:type owl:ObjectProperty ;
    rdfs:label "assigned to process" ;
    rdfs:comment "Links an invoice message to the business process it belongs to." ;
