#################################################################
# CONNECTIONS FOR DATA ELEMENTS
#################################################################

:hasCompositeElement rdf:type owl:ObjectProperty ;
    rdfs:label "has composite element" ;
    rdfs:comment "Links a segment to its composite data elements." ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement .

:compositeElementOf rdf:type owl:ObjectProperty ;
    rdfs:label "composite element of" ;
    rdfs:comment "Inverse of hasCompositeElement, links a composite data element to its segment." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    owl:inverseOf :hasCompositeElement .

:hasSimpleElement rdf:type owl:ObjectProperty ;
    rdfs:label "has simple element" ;
    rdfs:comment "Links a composite data element to its simple data elements." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement .

:simpleElementOf rdf:type owl:ObjectProperty ;
    rdfs:label "simple element of" ;
    rdfs:comment "Inverse of hasSimpleElement, links a simple data element to its composite data element." ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    owl:inverseOf :hasSimpleElement .

#################################################################
# PROPERTY CHARACTERISTICS
#################################################################

:hasMessage a owl:FunctionalProperty .
:hasHeader a owl:FunctionalProperty .
:hasDetail a owl:FunctionalProperty .
:hasSummary a owl:FunctionalProperty .

#################################################################
# ANNOTATIONS
#################################################################
# (All classes and properties above include rdfs:label and rdfs:comment)

#################################################################
# COMPLEX AXIOMS & RESTRICTIONS
#################################################################

:InvoiceMessage owl:equivalentClass [ rdf:type owl:Class ; owl:intersectionOf ( [ rdf:type owl:Restriction ; owl:onProperty :hasHeader ; owl:allValuesFrom :HeaderSection ] [ rdf:type owl:Restriction ; owl:onProperty :hasDetail ; owl:allValuesFrom :DetailSection ] [ rdf:type owl:Restriction ; owl:onProperty :hasSummary ; owl:allValuesFrom :SummarySection ] ) ] .

:LineItem owl:equivalentClass [ rdf:type owl:Class ; owl:intersectionOf ( [ rdf:type owl:Restriction ; owl:onProperty :aboutItem ; owl:someValuesFrom :Item ] [ rdf:type owl:Restriction ; owl:onProperty :hasNetPrice ; owl:someValuesFrom :Price ] [ rdf:type owl:Restriction ; owl:onProperty :hasQuantity ; owl:someValuesFrom xsd:decimal ] ) ] .

:OrganizationRoleAssignment owl:equivalentClass [ rdf:type owl:Class ; owl:intersectionOf ( [ rdf:type owl:Restriction ; owl:onProperty :involvesOrganization ; owl:someValuesFrom :Organization ] [ rdf:type owl:Restriction ; owl:onProperty :hasRole ; owl:someValuesFrom :AgentRole ] ) ] .

#################################################################
# INDIVIDUALS (EXAMPLES)
#################################################################
# (No individuals provided; ontology is schema-level)

args.value:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#EDIFACT_Invoice_Story>
    a owl:Ontology ;
    rdfs:label "EDIFACT Invoice Ontology" ;
    rdfs:comment "Ontology for representing EDIFACT invoice messages, segments, roles, and validation constraints in alignment with D96A/EANCOM and EN 16931-1." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The outermost envelope containing one or more messages as per EDIFACT." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message container." .

:InvoiceMessage a owl:Class ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "A message representing an EDIFACT invoice (e.g., INVOIC)." ;
    rdfs:subClassOf :Message .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment within an EDIFACT message." .

:BGMSegment a owl:Class ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." ;
    rdfs:subClassOf :Segment .

:NADSegment a owl:Class ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment for participant details." ;
    rdfs:subClassOf :Segment .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple (atomic) data element within a segment." .

:HeaderSection a owl:Class ;
    rdfs:label "Header Section" ;
    rdfs:comment "The header section of an invoice message, containing reference numbers and dates." ;
    rdfs:subClassOf :Segment .

:DetailSection a owl:Class ;
    rdfs:label "Detail Section" ;
    rdfs:comment "The detail section listing all line items in the invoice." ;
    rdfs:subClassOf :Segment .

:SummarySection a owl:Class ;
    rdfs:label "Summary Section" ;
    rdfs:comment "The summary section providing totals such as tax and invoice amount." ;
    rdfs:subClassOf :Segment .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "An itemized entry in the invoice detail section." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A company or entity involved in the invoice transaction." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the invoice context (e.g., Buyer, Seller, DeliveryParty)." .

:OrganizationalRoleAssignment a owl:Class ;
    rdfs:label "Organizational Role Assignment" ;
    rdfs:comment "A pivot class reifying the assignment of a role to an organization within a specific invoice context." ;
    rdfs:subClassOf :AgentRole .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal address associated with an organization." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "A generic identifier for organizations or items." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A globally unique location identifier for organizations." ;
    rdfs:subClassOf :Identifier .

:InvoiceAmount a owl:Class ;
    rdfs:label "Invoice Amount" ;
    rdfs:comment "The total amount of the invoice." .

:TaxAmount a owl:Class ;
    rdfs:label "Tax Amount" ;
    rdfs:comment "The total tax amount in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price value associated with a line item." .

:Quantity a owl:Class ;
    rdfs:label "Quantity" ;
    rdfs:comment "A quantity value associated with a line item." .

:ReferenceNumber a owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "A reference number for the invoice document." .

:DocumentDate a owl:Class ;
    rdfs:label "Document Date" ;
    rdfs:comment "The date of the invoice document." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice can be assigned." .

:Standard a owl:Class ;
    rdfs:label "Standard" ;
    rdfs:comment "A formal standard (e.g., EN 16931-1) to which the invoice aligns." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint used for automated validation of invoice data." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service listed in the invoice." .

:LineItemDetail a owl:Class ;
    rdfs:label "Line Item Detail" ;
    rdfs:comment "A pivot class reifying the details for a line item (e.g., price, quantity)." ;
    rdfs:subClassOf :DetailSection .

#################################################################
# Disjointness and Disjoint Unions
#################################################################

:InterchangeEnvelope owl:disjointWith :Message .
:Organization owl:disjointWith :Address .
:LineItem owl:disjointWith :Organization .
:HeaderSection owl:disjointWith :DetailSection , :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
:BGMSegment owl:disjointWith :NADSegment .
:CompositeDataElement owl:disjointWith :SimpleDataElement .

:Segment owl:disjointUnionOf (:BGMSegment :NADSegment :HeaderSection :DetailSection :SummarySection) .

#################################################################
# Object Properties
#################################################################

:containsMessage a owl:ObjectProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Relates an InterchangeEnvelope to its contained Message(s)." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    owl:FunctionalProperty .

:hasSegment a owl:ObjectProperty ;
    rdfs:label "has segment" ;
    rdfs:comment "Relates a Message to its Segments." ;
    rdfs:domain :Message ;
    rdfs:range :Segment .

:hasHeaderSection a owl:ObjectProperty ;
    rdfs:label "has header section" ;
    rdfs:comment "Relates an InvoiceMessage to its HeaderSection." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :HeaderSection ;
    owl:FunctionalProperty .

:hasDetailSection a owl:ObjectProperty ;
    rdfs:label "has detail section" ;
    rdfs:comment "Relates an InvoiceMessage to its DetailSection." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :DetailSection ;
    owl:FunctionalProperty .

:hasSummarySection a owl:ObjectProperty ;
    rdfs:label "has summary section" ;
    rdfs:comment "Relates an InvoiceMessage to its SummarySection." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :SummarySection ;
    owl:FunctionalProperty .

:hasLineItem a owl:ObjectProperty ;
    rdfs:label "has line item" ;
    rdfs:comment "Relates a DetailSection to its LineItems." ;
    rdfs:domain :DetailSection ;
    rdfs:range :LineItem .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Relates an InvoiceMessage to OrganizationalRoleAssignments." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :OrganizationalRoleAssignment .

:assignedRole a owl:ObjectProperty ;
    rdfs:label "assigned role" ;
    rdfs:comment "Relates an OrganizationalRoleAssignment to the AgentRole." ;
    rdfs:domain :OrganizationalRoleAssignment ;
    rdfs:range :AgentRole ;
    owl:FunctionalProperty .

:performedBy a owl:ObjectProperty ;
    rdfs:label "performed by" ;
    rdfs:comment "Relates an OrganizationalRoleAssignment to the Organization performing the role." ;
    rdfs:domain :OrganizationalRoleAssignment ;
    rdfs:range :Organization ;
    owl:FunctionalProperty .

:hasAddress a owl:ObjectProperty ;
    rdfs:label "has address" ;
    rdfs:comment "Relates an Organization to its Address." ;
    rdfs:domain :Organization ;
    rdfs:range :Address .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:label "has identifier" ;
    rdfs:comment "Relates an Organization to its Identifier(s)." ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier .

:hasGLN a owl:ObjectProperty ;
    rdfs:label "has GLN" ;
    rdfs:comment "Relates an Organization to its Global Location Number." ;
    rdfs:domain :Organization ;
    rdfs:range :GlobalLocationNumber ;
    owl:FunctionalProperty .

:playsRoleIn a owl:ObjectProperty ;
    rdfs:label "plays role in" ;
    rdfs:comment "Relates an Organization to the OrganizationalRoleAssignment(s) in which it participates." ;
    rdfs:domain :Organization ;
    rdfs:range :OrganizationalRoleAssignment .

:hasInvoiceAmount a owl:ObjectProperty ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "Relates a SummarySection to its InvoiceAmount." ;
    rdfs:domain :SummarySection ;
    rdfs:range :InvoiceAmount ;
    owl:FunctionalProperty .

:hasTaxAmount a owl:ObjectProperty ;
    rdfs:label "has tax amount" ;
    rdfs:comment "Relates a SummarySection to its TaxAmount." ;
    rdfs:domain :SummarySection ;
    rdfs:range :TaxAmount ;
    owl:FunctionalProperty .

:hasItem a owl:ObjectProperty ;
    rdfs:label "has item" ;
    rdfs:comment "Relates a LineItem to the Item it describes." ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    owl:FunctionalProperty .

:hasPrice a owl:ObjectProperty ;
    rdfs:label "has price" ;
    rdfs:comment "Relates a LineItem to its Price." ;
    rdfs:domain :LineItem ;
    rdfs:range :Price ;
    owl:FunctionalProperty .

:hasQuantity a owl:ObjectProperty ;
    rdfs:label "has quantity" ;
    rdfs:comment "Relates a LineItem to its Quantity." ;
    rdfs:domain :LineItem ;
    rdfs:range :Quantity ;
    owl:FunctionalProperty .

:hasBusinessProcess a owl:ObjectProperty ;
    rdfs:label "has business process" ;
    rdfs:comment "Relates an InvoiceMessage to a BusinessProcess." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    owl:FunctionalProperty .

:alignedWithStandard a owl:ObjectProperty ;
    rdfs:label "aligned with standard" ;
    rdfs:comment "Indicates the standard to which the invoice aligns." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Standard .

:validatedBy a owl:ObjectProperty ;
    rdfs:label "validated by" ;
    rdfs:comment "Indicates a validation constraint applied to the InvoiceMessage." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ValidationConstraint .

#################################################################
# Data Properties
#################################################################

:hasReferenceNumber a owl:DatatypeProperty ;
    rdfs:label "has reference number" ;
    rdfs:comment "The reference number in the header section." ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    owl:FunctionalProperty .

:hasDocumentDate a owl:DatatypeProperty ;
    rdfs:label "has document date" ;
    rdfs:comment "The document date in the header section." ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string ;
    owl:FunctionalProperty .

:hasValue a owl:DatatypeProperty ;
    rdfs:label "has value" ;
    rdfs:comment "The value of an amount, price, or quantity." ;
    rdfs:domain :InvoiceAmount, :TaxAmount, :Price, :Quantity ;
    rdfs:range xsd:decimal ;
    owl:FunctionalProperty .

:hasCurrency a owl:DatatypeProperty ;
    rdfs:label "has currency" ;
    rdfs:comment "The currency for an amount or price." ;
    rdfs:domain :InvoiceAmount, :TaxAmount, :Price ;
    rdfs:range xsd:string ;
    owl:FunctionalProperty .

