function.arguments:
{"key":"current_owl","value":"@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#EDIFACT_Invoice_Story>
    a owl:Ontology ;
    rdfs:label "EDIFACT Invoice Ontology" ;
    rdfs:comment "Ontology for representing EDIFACT invoice messages, segments, roles, and validation constraints in alignment with D96A/EANCOM and EN 16931-1." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The outermost envelope containing one or more messages as per EDIFACT." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message container." .

:InvoiceMessage a owl:Class ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "A message representing an EDIFACT invoice (e.g., INVOIC)." ;
    rdfs:subClassOf :Message .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment within an EDIFACT message." .

:BGMSegment a owl:Class ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." ;
    rdfs:subClassOf :Segment .

:NADSegment a owl:Class ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment for participant details." ;
    rdfs:subClassOf :Segment .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple (atomic) data element within a segment." .

:HeaderSection a owl:Class ;
    rdfs:label "Header Section" ;
    rdfs:comment "The header section of an invoice message, containing reference numbers and dates." ;
    rdfs:subClassOf :Segment .

:DetailSection a owl:Class ;
    rdfs:label "Detail Section" ;
    rdfs:comment "The detail section listing all line items in the invoice." ;
    rdfs:subClassOf :Segment .

:SummarySection a owl:Class ;
    rdfs:label "Summary Section" ;
    rdfs:comment "The summary section providing totals such as tax and invoice amount." ;
    rdfs:subClassOf :Segment .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "An itemized entry in the invoice detail section." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A company or entity involved in the invoice transaction." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the invoice context (e.g., Buyer, Seller, DeliveryParty)." .

:OrganizationalRoleAssignment a owl:Class ;
    rdfs:label "Organizational Role Assignment" ;
    rdfs:comment "A pivot class reifying the assignment of a role to an organization within a specific invoice context." ;
    rdfs:subClassOf :AgentRole .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal address associated with an organization." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "A generic identifier for organizations or items." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A globally unique location identifier for organizations." ;
    rdfs:subClassOf :Identifier .

:InvoiceAmount a owl:Class ;
    rdfs:label "Invoice Amount" ;
    rdfs:comment "The total amount of the invoice." .

:TaxAmount a owl:Class ;
    rdfs:label "Tax Amount" ;
    rdfs:comment "The total tax amount in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price value associated with a line item." .

:Quantity a owl:Class ;
    rdfs:label "Quantity" ;
    rdfs:comment "A quantity value associated with a line item." .

:ReferenceNumber a owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "A reference number for the invoice document." .

:DocumentDate a owl:Class ;
    rdfs:label "Document Date" ;
    rdfs:comment "The date of the invoice document." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice can be assigned." .

:Standard a owl:Class ;
    rdfs:label "Standard" ;
    rdfs:comment "A formal standard (e.g., EN 16931-1) to which the invoice aligns." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint used for automated validation of invoice data." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service listed in the invoice." .

:LineItemDetail a owl:Class ;
    rdfs:label "Line Item Detail" ;
    rdfs:comment "A pivot class reifying the details for a line item (e.g., price, quantity)." ;
    rdfs:subClassOf :DetailSection .

#################################################################
# Disjointness and Disjoint Unions
#################################################################

:InterchangeEnvelope owl:disjointWith :Message .
:Organization owl:disjointWith :Address .
:LineItem owl:disjointWith :Organization .
:HeaderSection owl:disjointWith :DetailSection , :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
:BGMSegment owl:disjointWith :NADSegment .
:CompositeDataElement owl:disjointWith :SimpleDataElement .

:Segment owl:disjointUnionOf (:BGMSegment :NADSegment :HeaderSection :DetailSection :SummarySection) .

#################################################################
# Object Properties
#################################################################

:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Relates an InterchangeEnvelope to its contained Message(s)." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message .
    owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope a owl:ObjectProperty ;
    rdfs:label "is contained in envelope" ;
    rdfs:comment "Inverse of containsMessage; relates a Message to its InterchangeEnvelope." ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope .
    owl:inverseOf :containsMessage .

:hasSegment a owl:ObjectProperty ;
    rdfs:label "has segment" ;
    rdfs:comment "Relates a Message to its Segments." ;
    rdfs:domain :Message ;
    rdfs:range :Segment .
    owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:label "is segment of" ;
    rdfs:comment "Inverse of hasSegment." ;
    rdfs:domain :Segment ;
    rdfs:range :Message .
    owl:inverseOf :hasSegment .

:hasHeaderSection a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has header section" ;
    rdfs:comment "Relates an InvoiceMessage to its HeaderSection." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :HeaderSection .
    owl:inverseOf :isHeaderSectionOf .

:isHeaderSectionOf a owl:ObjectProperty ;
    rdfs:label "is header section of" ;
    rdfs:comment "Inverse of hasHeaderSection." ;
    rdfs:domain :HeaderSection ;
    rdfs:range :InvoiceMessage .
    owl:inverseOf :hasHeaderSection .

:hasDetailSection a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has detail section" ;
    rdfs:comment "Relates an InvoiceMessage to its DetailSection." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :DetailSection .
    owl:inverseOf :isDetailSectionOf .

:isDetailSectionOf a owl:ObjectProperty ;
    rdfs:label "is detail section of" ;
    rdfs:comment "Inverse of hasDetailSection." ;
    rdfs:domain :DetailSection ;
    rdfs:range :InvoiceMessage .
    owl:inverseOf :hasDetailSection .

:hasSummarySection a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has summary section" ;
    rdfs:comment "Relates an InvoiceMessage to its SummarySection." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :SummarySection .
    owl:inverseOf :isSummarySectionOf .

:isSummarySectionOf a owl:ObjectProperty ;
    rdfs:label "is summary section of" ;
    rdfs:comment "Inverse of hasSummarySection." ;
    rdfs:domain :SummarySection ;
    rdfs:range :InvoiceMessage .
    owl:inverseOf :hasSummarySection .

:hasLineItem a owl:ObjectProperty ;
    rdfs:label "has line item" ;
    rdfs:comment "Relates a DetailSection to its LineItems." ;
    rdfs:domain :DetailSection ;
    rdfs:range :LineItem .
    owl:inverseOf :isLineItemOf .

:isLineItemOf a owl:ObjectProperty ;
    rdfs:label "is line item of" ;
    rdfs:comment "Inverse of hasLineItem." ;
    rdfs:domain :LineItem ;
    rdfs:range :DetailSection .
    owl:inverseOf :hasLineItem .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Relates an InvoiceMessage to OrganizationalRoleAssignments." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :OrganizationalRoleAssignment .
    owl:inverseOf :isRoleAssignmentOf .

:isRoleAssignmentOf a owl:ObjectProperty ;
    rdfs:label "is role assignment of" ;
    rdfs:comment "Inverse of hasRoleAssignment." ;
    rdfs:domain :OrganizationalRoleAssignment ;
    rdfs:range :InvoiceMessage .
    owl:inverseOf :hasRoleAssignment .

:assignedRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "assigned role" ;
    rdfs:comment "Relates an OrganizationalRoleAssignment to the AgentRole." ;
    rdfs:domain :OrganizationalRoleAssignment ;
    rdfs:range :AgentRole .
    owl:inverseOf :isRoleAssignedTo .

:isRoleAssignedTo a owl:ObjectProperty ;
    rdfs:label "is role assigned to" ;
    rdfs:comment "Inverse of assignedRole." ;
    rdfs:domain :AgentRole ;
    rdfs:range :OrganizationalRoleAssignment .
    owl:inverseOf :assignedRole .

:performedBy a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "performed by" ;
    rdfs:comment "Relates an OrganizationalRoleAssignment to the Organization performing the role." ;
    rdfs:domain :OrganizationalRoleAssignment ;
    rdfs:range :Organization .
    owl:inverseOf :performsRoleAssignment .

:performsRoleAssignment a owl:ObjectProperty ;
    rdfs:label "performs role assignment" ;
    rdfs:comment "Inverse of performedBy." ;
    rdfs:domain :Organization ;
    rdfs:range :OrganizationalRoleAssignment .
    owl:inverseOf :performedBy .

:hasAddress a owl:ObjectProperty ;
    rdfs:label "has address" ;
    rdfs:comment "Relates an Organization to its Address." ;
    rdfs:domain :Organization ;
    rdfs:range :Address .
    owl:inverseOf :isAddressOf .

:isAddressOf a owl:ObjectProperty ;
    rdfs:label "is address of" ;
    rdfs:comment "Inverse of hasAddress." ;
    rdfs:domain :Address ;
    rdfs:range :Organization .
    owl:inverseOf :hasAddress .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:label "has identifier" ;
    rdfs:comment "Relates an Organization to its Identifier(s)." ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier .
    owl:inverseOf :isIdentifierOf .

:isIdentifierOf a owl:ObjectProperty ;
    rdfs:label "is identifier of" ;
    rdfs:comment "Inverse of hasIdentifier." ;
    rdfs:domain :Identifier ;
    rdfs:range :Organization .
    owl:inverseOf :hasIdentifier .

:hasGLN a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has GLN" ;
    rdfs:comment "Relates an Organization to its Global Location Number." ;
    rdfs:domain :Organization ;
    rdfs:range :GlobalLocationNumber .
    owl:inverseOf :isGLNOf .

:isGLNOf a owl:ObjectProperty ;
    rdfs:label "is GLN of" ;
    rdfs:comment "Inverse of hasGLN." ;
    rdfs:domain :GlobalLocationNumber ;
    rdfs:range :Organization .
    owl:inverseOf :hasGLN .

:playsRoleIn a owl:ObjectProperty ;
    rdfs:label "plays role in" ;
    rdfs:comment "Relates an Organization to the OrganizationalRoleAssignment(s) in which it participates." ;
    rdfs:domain :Organization ;
    rdfs:range :OrganizationalRoleAssignment .
    owl:inverseOf :hasParticipant .

:hasParticipant a owl:ObjectProperty ;
    rdfs:label "has participant" ;
    rdfs:comment "Inverse of playsRoleIn." ;
    rdfs:domain :OrganizationalRoleAssignment ;
    rdfs:range :Organization .
    owl:inverseOf :playsRoleIn .

:hasInvoiceAmount a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "Relates a SummarySection to its InvoiceAmount." ;
    rdfs:domain :SummarySection ;
    rdfs:range :InvoiceAmount .
    owl:inverseOf :isInvoiceAmountOf .

:isInvoiceAmountOf a owl:ObjectProperty ;
    rdfs:label "is invoice amount of" ;
    rdfs:comment "Inverse of hasInvoiceAmount." ;
    rdfs:domain :InvoiceAmount ;
    rdfs:range :SummarySection .
    owl:inverseOf :hasInvoiceAmount .

:hasTaxAmount a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has tax amount" ;
    rdfs:comment "Relates a SummarySection to its TaxAmount." ;
    rdfs:domain :SummarySection ;
    rdfs:range :TaxAmount .
    owl:inverseOf :isTaxAmountOf .

:isTaxAmountOf a owl:ObjectProperty ;
    rdfs:label "is tax amount of" ;
    rdfs:comment "Inverse of hasTaxAmount." ;
    rdfs:domain :TaxAmount ;
    rdfs:range :SummarySection .
    owl:inverseOf :hasTaxAmount .

:hasItem a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has item" ;
    rdfs:comment "Relates a LineItem to the Item it describes." ;
    rdfs:domain :LineItem ;
    rdfs:range :Item .
    owl:inverseOf :isItemOf .

:isItemOf a owl:ObjectProperty ;
    rdfs:label "is item of" ;
    rdfs:comment "Inverse of hasItem." ;
    rdfs:domain :Item ;
    rdfs:range :LineItem .
    owl:inverseOf :hasItem .

:hasPrice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has price" ;
    rdfs:comment "Relates a LineItem to its Price." ;
    rdfs:domain :LineItem ;
    rdfs:range :Price .
    owl:inverseOf :isPriceOf .

:isPriceOf a owl:ObjectProperty ;
    rdfs:label "is price of" ;
    rdfs:comment "Inverse of hasPrice." ;
    rdfs:domain :Price ;
    rdfs:range :LineItem .
    owl:inverseOf :hasPrice .

:hasQuantity a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has quantity" ;
    rdfs:comment "Relates a LineItem to its Quantity." ;
    rdfs:domain :LineItem ;
    rdfs:range :Quantity .
    owl:inverseOf :isQuantityOf .

:isQuantityOf a owl:ObjectProperty ;
    rdfs:label "is quantity of" ;
    rdfs:comment "Inverse of hasQuantity." ;
    rdfs:domain :Quantity ;
    rdfs:range :LineItem .
    owl:inverseOf :hasQuantity .

:hasBusinessProcess a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has business process" ;
    rdfs:comment "Relates an InvoiceMessage to a BusinessProcess." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess .
    owl:inverseOf :isBusinessProcessOf .

:isBusinessProcessOf a owl:ObjectProperty ;
    rdfs:label "is business process of" ;
    rdfs:comment "Inverse of hasBusinessProcess." ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :InvoiceMessage .
    owl:inverseOf :hasBusinessProcess .

:alignedWithStandard a owl:ObjectProperty ;
    rdfs:label "aligned with standard" ;
    rdfs:comment "Indicates the standard to which the invoice aligns." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Standard .
    owl:inverseOf :isStandardFor .

:isStandardFor a owl:ObjectProperty ;
    rdfs:label "is standard for" ;
    rdfs:comment "Inverse of alignedWithStandard." ;
    rdfs:domain :Standard ;
    rdfs:range :InvoiceMessage .
    owl:inverseOf :alignedWithStandard .

:validatedBy a owl:ObjectProperty ;
    rdfs:label "validated by" ;
    rdfs:comment "Indicates a validation constraint applied to the InvoiceMessage." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ValidationConstraint .
    owl:inverseOf :validates .

:validates a owl:ObjectProperty ;
    rdfs:label "validates" ;
    rdfs:comment "Inverse of validatedBy." ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range :InvoiceMessage .
    owl:inverseOf :validatedBy .

#################################################################
# Data Properties
#################################################################

:hasReferenceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has reference number" ;
    rdfs:comment "The reference number in the header section." ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string .

:hasDocumentDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has document date" ;
    rdfs:comment "The document date in the header section." ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:string .

:hasInvoiceAmountValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has invoice amount value" ;
    rdfs:comment "The value of the total invoice amount." ;
    rdfs:domain :InvoiceAmount ;
    rdfs:range xsd:decimal .

:hasTaxAmountValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has tax amount value" ;
    rdfs:comment "The value of the total tax amount." ;
    rdfs:domain :TaxAmount ;
    rdfs:range xsd:decimal .

:hasPriceValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has price value" ;
    rdfs:comment "The value of a price." ;
    rdfs:domain :Price ;
    rdfs:range xsd:decimal .

:hasQuantityValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has quantity value" ;
    rdfs:comment "The value of a quantity." ;
    rdfs:domain :Quantity ;
    rdfs:range xsd:decimal .

:hasInvoiceAmountCurrency a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has invoice amount currency" ;
    rdfs:comment "The currency for the invoice amount." ;
    rdfs:domain :InvoiceAmount ;
    rdfs:range xsd:string .

:hasTaxAmountCurrency a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has tax amount currency" ;
    rdfs:comment "The currency for the tax amount." ;
    rdfs:domain :TaxAmount ;
    rdfs:range xsd:string .

:hasPriceCurrency a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has price currency" ;
    rdfs:comment "The currency for a price." ;
    rdfs:domain :Price ;
    rdfs:range xsd:string .

:hasItemDescription a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has item description" ;
    rdfs:comment "A description for an item." ;
    rdfs:domain :Item ;
    rdfs:range xsd:string .

:hasAddressLine a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has address line" ;
    rdfs:comment "The address line for an address." ;
    rdfs:domain :Address ;
    rdfs:range xsd:string .

:hasPostalCode a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has postal code" ;
    rdfs:comment "The postal code for an address." ;
    rdfs:domain :Address ;
    rdfs:range xsd:string .

:hasCity a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has city" ;
    rdfs:comment "The city for an address." ;
    rdfs:domain :Address ;
    rdfs:range xsd:string .

:hasCountry a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has country" ;
    rdfs:comment "The country for an address." ;
    rdfs:domain :Address ;
    rdfs:range xsd:string .

#################################################################
# Connections for Unconnected Elements
#################################################################

:hasCompositeDataElement a owl:ObjectProperty ;
    rdfs:label "has composite data element" ;
    rdfs:comment "Connects a Segment to a CompositeDataElement." ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement .
    owl:inverseOf :isCompositeDataElementOf .

:isCompositeDataElementOf a owl:ObjectProperty ;
    rdfs:label "is composite data element of" ;
    rdfs:comment "Inverse of hasCompositeDataElement." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment .
    owl:inverseOf :hasCompositeDataElement .

:hasSimpleDataElement a owl:ObjectProperty ;
    rdfs:label "has simple data element" ;
    rdfs:comment "Connects a CompositeDataElement to a SimpleDataElement." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement .
    owl:inverseOf :isSimpleDataElementOf .

:isSimpleDataElementOf a owl:ObjectProperty ;
    rdfs:label "is simple data element of" ;
    rdfs:comment "Inverse of hasSimpleDataElement." ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement .
    owl:inverseOf :hasSimpleDataElement .

:referencesNumber a owl:ObjectProperty ;
    rdfs:label "references number" ;
    rdfs:comment "Connects a HeaderSection to a ReferenceNumber." ;
    rdfs:domain :HeaderSection ;
    rdfs:range :ReferenceNumber .
    owl:inverseOf :isReferenceNumberOf .

:isReferenceNumberOf a owl:ObjectProperty ;
    rdfs:label "is reference number of" ;
    rdfs:comment "Inverse of referencesNumber." ;
    rdfs:domain :ReferenceNumber ;
    rdfs:range :HeaderSection .
    owl:inverseOf :referencesNumber .

:referencesDocumentDate a owl:ObjectProperty ;
    rdfs:label "references document date" ;
    rdfs:comment "Connects a HeaderSection to a DocumentDate." ;
    rdfs:domain :HeaderSection ;
    rdfs:range :DocumentDate .
    owl:inverseOf :isDocumentDateOf .

:isDocumentDateOf a owl:ObjectProperty ;
    rdfs:label "is document date of" ;
    rdfs:comment "Inverse of referencesDocumentDate." ;
    rdfs:domain :DocumentDate ;
    rdfs:range :HeaderSection .
    owl:inverseOf :referencesDocumentDate .

#################################################################
# Restrictions and Advanced Modeling
#################################################################

:InvoiceMessage rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :hasRoleAssignment ;
    owl:allValuesFrom :OrganizationalRoleAssignment
] .

:OrganizationalRoleAssignment rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :assignedRole ;
    owl:someValuesFrom :AgentRole
] , [
    a owl:Restriction ;
    owl:onProperty :performedBy ;
    owl:someValuesFrom :Organization
] .

:LineItem rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :hasPrice ;
    owl:allValuesFrom :Price
] .

#################################################################
# Annotations (rdfs:label and rdfs:comment already included above)
#################################################################
"}

args.owl_content:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#EDIFACT_Invoice_Story>
    a owl:Ontology ;
    rdfs:label "EDIFACT Invoice Ontology" ;
    rdfs:comment "Ontology for representing EDIFACT invoice messages, segments, roles, and validation constraints in alignment with D96A/EANCOM and EN 16931-1." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The outermost envelope containing one or more messages as per EDIFACT." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message container." .

:InvoiceMessage a owl:Class ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "A message representing an EDIFACT invoice (e.g., INVOIC)." ;
    rdfs:subClassOf :Message .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment within an EDIFACT message." .

:BGMSegment a owl:Class ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." ;
    rdfs:subClassOf :Segment .

:NADSegment a owl:Class ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment for participant details." ;
    rdfs:subClassOf :Segment .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple (atomic) data element within a segment." .

:HeaderSection a owl:Class ;
    rdfs:label "Header Section" ;
    rdfs:comment "The header section of an invoice message, containing reference numbers and dates." ;
    rdfs:subClassOf :Segment .

:DetailSection a owl:Class ;
    rdfs:label "Detail Section" ;
    rdfs:comment "The detail section listing all line items in the invoice." ;
    rdfs:subClassOf :Segment .

:SummarySection a owl:Class ;
    rdfs:label "Summary Section" ;
    rdfs:comment "The summary section providing totals such as tax and invoice amount." ;
    rdfs:subClassOf :Segment .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "An itemized entry in the invoice detail section." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A company or entity involved in the invoice transaction." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the invoice context (e.g., Buyer, Seller, DeliveryParty)." .

:OrganizationalRoleAssignment a owl:Class ;
    rdfs:label "Organizational Role Assignment" ;
    rdfs:comment "A pivot class reifying the assignment of a role to an organization within a specific invoice context." ;
    rdfs:subClassOf :AgentRole .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal address associated with an organization." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "A generic identifier for organizations or items." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A globally unique location identifier for organizations." ;
    rdfs:subClassOf :Identifier .

:InvoiceAmount a owl:Class ;
    rdfs:label "Invoice Amount" ;
    rdfs:comment "The total amount of the invoice." .

:TaxAmount a owl:Class ;
    rdfs:label "Tax Amount" ;
    rdfs:comment "The total tax amount in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price value associated with a line item." .

:Quantity a owl:Class ;
    rdfs:label "Quantity" ;
    rdfs:comment "A quantity value associated with a line item." .

:ReferenceNumber a owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "A reference number for the invoice document." .

:DocumentDate a owl:Class ;
    rdfs:label "Document Date" ;
    rdfs:comment "The date of the invoice document." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice can be assigned." .

:Standard a owl:Class ;
    rdfs:label "Standard" ;
    rdfs:comment "A formal standard (e.g., EN 16931-1) to which the invoice aligns." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint used for automated validation of invoice data." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service listed in the invoice." .

:LineItemDetail a owl:Class ;
    rdfs:label "Line Item Detail" ;
    rdfs:comment "A pivot class reifying the details for a line item (e.g., price, quantity)." ;
    rdfs:subClassOf :DetailSection .

#################################################################
# Disjointness and Disjoint Unions
#################################################################

:InterchangeEnvelope owl:disjointWith :Message .
:Organization owl:disjointWith :Address .
:LineItem owl:disjointWith :Organization .
:HeaderSection owl:disjointWith :DetailSection , :SummarySection .
:DetailSection owl:disjointWith :SummarySection .
:BGMSegment owl:disjointWith :NADSegment .
:CompositeDataElement owl:disjointWith :SimpleDataElement .

:Segment owl:disjointUnionOf (:BGMSegment :NADSegment :HeaderSection :DetailSection :SummarySection) .

#################################################################
# Object Properties
#################################################################

:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Relates an InterchangeEnvelope to its contained Message(s)." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope a owl:ObjectProperty ;
    rdfs:label "is contained in envelope" ;
    rdfs:comment "Inverse of containsMessage; relates a Message to its InterchangeEnvelope." ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    owl:inverseOf :containsMessage .

:hasSegment a owl:ObjectProperty ;
    rdfs:label "has segment" ;
    rdfs:comment "Relates a Message to its Segments." ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:label "is segment of" ;
    rdfs:comment "Inverse of hasSegment." ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    owl:inverseOf :hasSegment .

:hasHeaderSection a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has header section" ;
    rdfs:comment "Relates an InvoiceMessage to its HeaderSection." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :HeaderSection ;
    owl:inverseOf :isHeaderSectionOf .

:isHeaderSectionOf a owl:ObjectProperty ;
    rdfs:label "is header section of" ;
    rdfs:comment "Inverse of hasHeaderSection." ;
    rdfs:domain :HeaderSection ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasHeaderSection .

:hasDetailSection a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has detail section" ;
    rdfs:comment "Relates an InvoiceMessage to its DetailSection." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :DetailSection ;
    owl:inverseOf :isDetailSectionOf .

:isDetailSectionOf a owl:ObjectProperty ;
    rdfs:label "is detail section of" ;
    rdfs:comment "Inverse of hasDetailSection." ;
    rdfs:domain :DetailSection ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasDetailSection .

:hasSummarySection a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has summary section" ;
    rdfs:comment "Relates an InvoiceMessage to its SummarySection." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :SummarySection ;
    owl:inverseOf :isSummarySectionOf .

:isSummarySectionOf a owl:ObjectProperty ;
    rdfs:label "is summary section of" ;
    rdfs:comment "Inverse of hasSummarySection." ;
    rdfs:domain :SummarySection ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasSummarySection .

:hasLineItem a owl:ObjectProperty ;
    rdfs:label "has line item" ;
    rdfs:comment "Relates a DetailSection to its LineItems." ;
    rdfs:domain :DetailSection ;
    rdfs:range :LineItem ;
    owl:inverseOf :isLineItemOf .

:isLineItemOf a owl:ObjectProperty ;
    rdfs:label "is line item of" ;
    rdfs:comment "Inverse of hasLineItem." ;
    rdfs:domain :LineItem ;
    rdfs:range :DetailSection ;
    owl:inverseOf :hasLineItem .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Relates an InvoiceMessage to OrganizationalRoleAssignments." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :OrganizationalRoleAssignment ;
    owl:inverseOf :isRoleAssignmentOf .

:isRoleAssignmentOf a owl:ObjectProperty ;
    rdfs:label "is role assignment of" ;
